INSERT INTO `chat_message` VALUES (149, 53, 'assistant', '我需要查询知识库中所有文档和视频的学习状态，然后统计未学习的文档数量。\n\n1. 【文档ID: 1】赋注解属性工具 — learned  \n2. 【文档ID: 2】赋属性工具 — learned  \n3. 【文档ID: 3】建模出图工具 — learned  \n4. 【文档ID: 4】BOM工具 — learned  \n5. 【文档ID: 5】快速涂色赋注解 — learned  \n6. 【文档ID: 6】建模档合并订料 — learned  \n7. 【文档ID: 7】零件刻字 — learned  \n8. 【文档ID: 8】快速涂色 — learned  \n9. 【文档ID: 9】出图预设 — learned  \n10. 【视频ID: 1】赋注解属性.mp4 — unlearned(所属功能ID: 1)  \n\n共 9 篇文档(已学习 9 篇, 未学习 0 篇); 共 1 个视频(已学习 0 个, 未学习 1 个)', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.42475694},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3997259},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.55455697},{\"featureName\":\"零件刻字\",\"chunkType\":\"error_solution\",\"score\":0.50845295},{\"featureName\":\"零件刻字\",\"chunkType\":\"error_solution\",\"score\":0.50845295}]', NULL, NULL, NULL, NULL, '2026-05-18 19:21:21', 0, NULL, NULL);
