INSERT INTO `chat_message` VALUES (161, 55, 'assistant', '您在使用「快速涂色」功能时，因**未设置出图标准**导致系统无法加载配置表，从而弹出“找不到配置表”提示。\n\n可能原因及解决步骤如下：\n\n1. **根本原因**：未进入【建模档出图标准设置】并选择设计标准（如“启泰”），导致特征注解表和材质颜色表路径无法定位；  \n2. **解决方法**：  \n   - 进入【建模档出图标准设置】；  \n   - 手动选择对应品牌的设计标准（例如：启泰）；  \n   - 再次打开「快速涂色」，确认可正常加载配置表并执行上色。  \n\n**如何预防**：每次启动该功能前，务必先完成设计标准设置；建议在项目初始化阶段将标准固化为默认项。(参考: 快速涂色-error_solution)', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.8549825},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.5671376},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.8853893},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8028871},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.7545009}]', NULL, -1, '666', '2026-05-18 19:59:17', '2026-05-18 19:59:07', 0, NULL, NULL);
