INSERT INTO `chat_message` VALUES (164, 57, 'user', '最近有哪些问题被问的比较多？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-18 20:13:05', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (165, 57, 'assistant', '根据近期常见问题（FAQ），被问得较多的有以下两类：\n\n1. **蓝U登录异常**  \n   - 提示“已在其他电脑登录”：建议等待约15秒后重试，或检查网络；长期失败可联系运维。  \n   - 提示“密码错误”：默认密码为注册手机号；多次失败请联系管理员。\n\n2. **快速涂色赋注解相关**  \n   - 出现“抄底注释”：表示系统未识别孔特征或材质配置，**不可直接视为完成**，需人工复核三要素：①孔特征识别是否正确；②材质是否在「材质颜色表」中；③配色是否已配置。  \n   - 操作前必须先选择「设计标准」，否则会弹出错误提示并阻断分析与上色。（参考: 快速涂色赋注解-caution / prerequisite）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.40187097},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.399862},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"caution\",\"score\":0.5104171},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"caution\",\"score\":0.5104171},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"prerequisite\",\"score\":0.5066674},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"prerequisite\",\"score\":0.5066674}]', NULL, NULL, NULL, NULL, '2026-05-18 20:13:12', 0, NULL, NULL);
