INSERT INTO `chat_message` VALUES (168, 59, 'user', 'BOM 工具怎么用？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-19 11:16:26', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (169, 59, 'assistant', '以下是使用 BOM 工具的完整操作步骤（参考知识库操作指南）：\n\n1. **填写并检查客户信息、模号、产品编号**（位于工具主界面顶部输入区）  \n2. **选择 BOM 表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：  \n　　- ✅ 已备料不出料单  \n　　- ✅ 是否分页 → 设置**分页类型和行数**（注意：行数不可超过原表格最大行数，如 20，否则导致乱码）  \n4. **生成 BOM 数据**：  \n　　- 点击**扫描所有实体**（全图档）或**选择实体生成**（仅选中对象）  \n5. **导出结果**：点击**导出EXCEL**；导出后如需文本，可再点**EXCEL转TXT文本**  \n\n⚠️ 前置条件：必须完成步骤1～3后，步骤4扫描才有正确表头与字段；未扫描则步骤5导出为空或报错。  \n（参考: BOM工具-operation_guide）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.5319384},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3246295},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8100414},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6968995},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.68929535}]', NULL, NULL, NULL, NULL, '2026-05-19 11:16:33', 0, NULL, NULL);
