INSERT INTO `chat_message` VALUES (190, 69, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:19:12', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (191, 69, 'assistant', '关于该提示框“已执行某项操作，该操作可删除……此对话框即将关闭”，知识库中未提供对应的操作指引或处理说明。\n\n该提示可能出现在特定功能模块（如数据清理、临时任务执行等）中，但当前知识片段中无相关界面逻辑、关闭机制或后续影响说明。\n\n关于这个问题，我目前的知识库暂未覆盖完整答案。需要我帮您提交工单，让技术人员进一步协助吗？', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645}]', NULL, NULL, NULL, NULL, '2026-05-20 14:19:23', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (192, 70, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:19:23', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (193, 70, 'assistant', '您描述的是执行「删除属性」操作后出现的提示框，根据知识库内容，该提示框属于**赋属性工具**的正常反馈。但请注意：\n\n1. **该提示仅表示操作已触发，并不等于删除成功**；  \n2. 必须在弹出确认框后点击 **“确定”**，才能使删除真正生效；  \n3. 若仅点击“删除属性”按钮就关闭提示框，而未点“确定”，则属性**实际未被删除**。\n\n请务必在提示框出现后，主动点击 **“确定”** 完成提交。（参考: 赋属性工具-caution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6003254}]', NULL, NULL, NULL, NULL, '2026-05-20 14:19:30', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (194, 71, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:19:30', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (195, 71, 'assistant', '该提示框是系统执行某项操作（如删除、清理等）后的自动反馈，通常为**短暂弹窗**，几秒后自动关闭，无需手动点击。\n\n如您希望：\n- **延长显示时间**：目前该提示框无手动停留功能，属系统默认行为；\n- **取消该操作**：提示框出现前应有确认步骤（如“确定删除？”），一旦弹出“已执行”则操作已完成，不可撤销；\n- **关闭提示框**：可按 **Enter 键** 或点击提示框任意位置（部分版本支持）加速关闭。\n\n若提示频繁出现、无法关闭、或操作非预期，请提供具体场景（如在哪个界面/执行什么操作后出现），我可进一步协助判断是否异常。（参考:通用交互提示-系统反馈机制）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645}]', NULL, NULL, NULL, NULL, '2026-05-20 14:19:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (196, 72, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:19:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (197, 72, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**  \n   - 错误原因：导出时“分页行数”设为＞20（如40），超出系统单页最大允许行数（默认20），导致分页逻辑异常、数据错位或截断。  \n   - 解决：重新导出，将**分页行数严格设为≤20**（推荐20或更低，如15）。\n\n2. **未先扫描BOM表就导出**  \n   - 错误原因：“扫描所有实体出BOM表”是导出前提，未扫描则内存无数据源，导出结果不可控。  \n   - 解决：执行**步骤四“扫描所有实体出BOM表”后再导出**。\n\n✅ 预防措施：导出前务必检查分页行数是否≤20，并确保已完成扫描动作。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3348278},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.90973794},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-20 14:19:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (198, 73, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:19:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (199, 73, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**  \n   - 错误原因：导出时“分页行数”设为＞20（如40），超出系统单页最大允许行数，导致数据错位或截断。  \n   - 解决：重新导出，将**分页行数严格设为≤20**（推荐20、15或10）。\n\n2. **未先扫描BOM表即导出**  \n   - 错误原因：导出操作依赖扫描生成的数据源；未扫描则内存无完整BOM数据，易引发行序异常。  \n   - 解决：执行**步骤四“扫描所有实体出BOM表”后再导出**。\n\n3. **总行数与分页不匹配**  \n   - 例：BOM共35行，设分页20 → 第2页仅15行，TXT转换时解析异常。  \n   - 解决：按实际总行数合理设定分页值，优先保守使用≤20。\n\n✅ 预防措施：导出前务必检查“是否分页”勾选状态，并确认分页行数输入框数值≤20。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3348278},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.90973794},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-20 14:19:52', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (200, 74, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:19:52', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (201, 74, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**  \n   - 错误原因：导出时“分页行数”设为＞20（如40），超出系统单页最大允许行数（默认20），导致分页逻辑异常、数据错位或截断。  \n   - 解决：重新导出，将**分页行数严格设为≤20**（推荐20或更低，如15）。\n\n2. **未先扫描BOM表就导出**  \n   - 错误原因：导出操作依赖扫描生成的数据源；未扫描则内存无完整BOM数据，导出结果不可靠。  \n   - 解决：先执行「扫描所有实体出BOM表」，再导出Excel。\n\n✅ 预防措施：导出前务必检查「步骤三」中分页行数输入框，默认值或惯性填入“40”会直接触发乱码。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3348278},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.90973794},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-20 14:19:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (202, 75, 'user', '为甚使用BOM导出TXT文本失败？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:19:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (203, 75, 'assistant', '您遇到的是 **BOM导出TXT文本失败** 的问题。可能原因及解决步骤如下：\n\n1. **按钮灰显/不可用**  \n   - 原因：未先执行“导出EXCEL表”操作，TXT转换功能有强前置依赖。  \n   - 解决：务必先完成**步骤五：点击导出EXCEL**，待弹出保存提示、EXCEL文件成功生成后，再点击“EXCEL转TXT文本”。\n\n2. **导出后乱码或失败**  \n   - 原因：导出EXCEL时设置的“分页行数”超过系统安全阈值（如设为40，但应≤20）。  \n   - 解决：重新导出EXCEL，将**分页行数严格设为≤20**（推荐20），避免数据错位或解析异常。\n\n**预防建议**：操作前确认已执行导出EXCEL；在勾选“分页”时主动检查并输入≤20的数值——默认填40是常见错误源头。(参考: BOM工具-error_solution)', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.6282047},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.4548791},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8719525},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8615391},{\"featureName\":\"BOM工具\",\"chunkType\":\"prerequisite\",\"score\":0.7545464},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.719066}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:05', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (204, 76, 'user', '为甚使用BOM导出TXT文本失败？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:06', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (205, 76, 'assistant', '您遇到的是 **BOM导出TXT文本失败** 的问题。可能原因及解决步骤如下：\n\n1. **按钮灰显/不可用**  \n   - 原因：未先执行“导出EXCEL表”操作，TXT转换功能有强前置依赖。  \n   - 解决：务必先完成**步骤五：点击导出EXCEL**，待弹出保存提示、EXCEL文件成功生成后，再点击“EXCEL转TXT文本”。\n\n2. **导出后乱码或失败**  \n   - 原因：导出EXCEL时设置的“分页行数”超过系统安全阈值（如设为40，但应≤20）。  \n   - 解决：重新导出EXCEL，将**分页行数严格设为≤20**（推荐20），避免数据错位或解析异常。\n\n**预防建议**：操作前确认已导出EXCEL；勾选“分页”时主动检查并修正分页行数值，默认40会直接触发故障。(参考: BOM工具-error_solution)', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.6282047},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.4548791},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8719525},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8615391},{\"featureName\":\"BOM工具\",\"chunkType\":\"prerequisite\",\"score\":0.7545464},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.719066}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:12', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (206, 77, 'user', '为甚使用BOM导出TXT文本失败？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:12', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (207, 77, 'assistant', '您遇到的是 **BOM导出TXT文本失败** 的问题。可能原因及解决步骤如下：\n\n1. **按钮灰显/不可用**  \n   - 原因：未先执行“导出EXCEL表”操作，TXT转换功能依赖EXCEL已生成。  \n   - 解决：务必先完成**步骤五：点击导出EXCEL**，待保存提示弹出后再点“EXCEL转TXT文本”。\n\n2. **导出后乱码或无响应**  \n   - 原因：导出EXCEL时设置的**分页行数 > 20**（如填40），超出系统分页逻辑容限。  \n   - 解决：重新导出EXCEL，将“分页行数”设为**≤20**（保守推荐值）。\n\n3. **其他前置未满足**  \n   - 确认是否已完成BOM表类型选择、实体扫描等基础步骤（步骤二至四）。\n\n✅ 预防建议：将“导出EXCEL”作为TXT转换的强制前置动作，并在设置分页时默认检查并锁定≤20行。（参考: BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.6282047},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.4548791},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8719525},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8615391},{\"featureName\":\"BOM工具\",\"chunkType\":\"prerequisite\",\"score\":0.7545464},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.719066}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:20', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (208, 78, 'user', '我在使用快速涂色功能的时候,为什么上色功能失败？弹出个提示框,说是找不到配置表。', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:20', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (209, 78, 'assistant', '您在使用「快速涂色」时遇到“找不到配置表”的提示，说明系统无法加载所需的配置文件。\n\n可能原因及解决步骤如下：\n\n1. **未设置出图标准**（最常见）  \n　→ 进入【建模档出图标准设置】，手动选择对应品牌的设计标准（如“启泰”）。\n\n2. **特征注解表或材质颜色表未配置**  \n　→ 在设置标准后，依次打开【特征注解表】和【材质颜色表】，完成参数配置。\n\n3. **配置表路径异常或缺失**  \n　→ 检查软件安装目录下配置表是否存在；若缺失，联系实施人员补发。\n\n预防措施：每次使用前先确认已设置设计标准，并将标准配置固化为项目默认项。（参考: 快速涂色-error_solution）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.8587271},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.55851966},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.87974805},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8012762},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.75509983}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:25', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (210, 79, 'user', '我在使用快速涂色功能的时候,为什么上色功能失败？弹出个提示框,说是找不到配置表。', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:26', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (211, 79, 'assistant', '您在使用「快速涂色」时遇到“找不到配置表”的提示，说明系统无法加载所需的配置文件。\n\n可能原因及解决步骤如下：\n\n1. **未设置出图标准**（最常见）  \n　→ 进入【建模档出图标准设置】，选择对应品牌标准（如“启泰”）；  \n2. **未完成参数配置**  \n　→ 分别打开【特征注解表】和【材质颜色表】，确保已正确配置；  \n3. **配置表路径异常或缺失**  \n　→ 检查软件安装目录下配置表文件是否存在，必要时重装或联系实施更新。\n\n**预防建议**：每次启动「快速涂色」前，务必先完成出图标准设置，并将常用标准设为默认项。（参考: 快速涂色-error_solution）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.8587271},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.55851966},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.87974805},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8012762},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.75509983}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:31', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (212, 80, 'user', '我在使用快速涂色功能的时候,为什么上色功能失败？弹出个提示框,说是找不到配置表。', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:31', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (213, 80, 'assistant', '您在使用「快速涂色」时遇到“找不到配置表”的提示，**根本原因是未预先设置建模档出图标准**（如“启泰”标准），导致系统无法加载特征注解表和材质颜色表。\n\n可能原因与解决步骤如下：\n\n1. **未设置设计标准**  \n　→ 进入【建模档出图标准设置】，手动选择对应品牌标准（如“启泰”）。\n\n2. **虽设标准但配置表未加载**  \n　→ 在「快速涂色」界面，依次点击：  \n　　• “特征注解表” → “打开配置表”；  \n　　• “材质颜色表” → “打开配置表”，完成参数配置。\n\n3. **配置后仍异常**  \n　→ 检查体/孔/键槽是否显示为**红色字体**（表示未识别特征），确认标准与配置表匹配。\n\n✅ 预防建议：每次启动「快速涂色」前，务必先完成出图标准设置；项目初始化时可将标准固化为默认项。(参考: 快速涂色-error_solution)', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.8587271},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.55851966},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.87974805},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8012762},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.75509983}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:38', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (214, 81, 'user', '使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要怎么改？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:38', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (215, 81, 'assistant', '根据知识库，该提示出现是因为勾选「重量」功能后设置了重量预值，且当前备料板估算重量超过该预值。修改方法如下：\n\n1. **打开「预设值」设置**：在建模档合并订料界面，找到并点击「预设值」按钮；  \n2. **调整重量预值**：在弹出的设置中，将「重量」预值修改为更大数值，或设为 **0（表示不限重）**；  \n3. **同步优化备料内容**（可选）：若需保留重量限制，可减少备料板内工件数量，或更换密度更低的材质工件；  \n4. **验证估算合理性**：建议先用「外形尺寸」结合材料密度粗估总重，再设定合理预值。\n\n（参考: 建模档合并订料-error_solution）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/0b3e241de6c84fea99d8a880fe21bb89.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d998d701cc314fa396a996180e38e31e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6c796acc3d604f92a84eccaa72960524.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.94574517},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37372708},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"error_solution\",\"score\":0.9105971},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"operation_guide\",\"score\":0.903606},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.78844434}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (216, 82, 'user', '使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要怎么改？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (217, 82, 'assistant', '根据知识库信息，当「建模档合并订料」弹出“备料板重量超出限定值”提示时，说明当前备料板估算重量超过了预设的重量阈值。以下是具体修改步骤：\n\n1. **打开「预设值」设置**：在建模档合并订料界面，找到并点击「预设值」功能区；  \n2. **调整重量预值**：勾选「重量」选项，在对应输入框中**将预设重量值调大，或设为0（表示不限重）**；  \n3. **同步优化备料内容**（可选）：若需保留重量限制，可减少单板工件数量、移除较重工件，或更换密度更低的材质；  \n4. **验证外形尺寸与重量匹配性**：建议先用「外形尺寸」结合材料密度粗估总重，再设定合理预值，避免误报。（参考:建模档合并订料-error_solution）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/0b3e241de6c84fea99d8a880fe21bb89.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d998d701cc314fa396a996180e38e31e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6c796acc3d604f92a84eccaa72960524.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.94574517},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37372708},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"error_solution\",\"score\":0.9105971},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"operation_guide\",\"score\":0.903606},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.78844434}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:51', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (218, 83, 'user', '使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要怎么改？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:51', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (219, 83, 'assistant', '根据知识库，该提示出现是因为勾选「重量」功能后设置了重量预值，且当前备料板估算重量超过该预值。修改方法如下：\n\n1. **修改重量预值**：在「预设值」步骤中，将「重量」预值调大（或设为0表示不限）；  \n2. **优化备料内容**：减少备料板内工件数量，或更换密度更低的材质工件；  \n3. **前置估算**：设置预值前，先通过「外形尺寸」×材料密度粗估总重，避免预设失当。\n\n（参考: 建模档合并订料-error_solution）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/0b3e241de6c84fea99d8a880fe21bb89.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d998d701cc314fa396a996180e38e31e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6c796acc3d604f92a84eccaa72960524.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.94574517},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37372708},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"error_solution\",\"score\":0.9105971},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"operation_guide\",\"score\":0.903606},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.78844434}]', NULL, NULL, NULL, NULL, '2026-05-20 14:20:56', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (220, 84, 'user', '赋属性工具中编辑原点的功能有什么作用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:20:56', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (221, 84, 'assistant', '**编辑原点**功能用于检查和修改单个或批量工件的原点位置，是确保后续属性赋值（如零件编号、长宽高、重量等）准确性的关键前置步骤。\n\n典型应用场景包括：\n1. **批量校准坯料原点**：当多个工件原点偏移时，统一调整至设计基准；\n2. **适配不同建模习惯**：支持设置原点为“四面分中”或“左下角”，匹配客户标准；\n3. **出图准备验证**：配合「检查原点」显示所有坯料框，直观确认原点是否对齐。\n\n该功能属于「赋属性工具」的核心子功能，必须在勾选「检查原点」后才能操作，且需完成「应用更新」和「确定」才能持久化修改。（参考: 赋属性工具 - feature_detail）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.27905914},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.25713286},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_detail\",\"score\":0.835248},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7581718}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:03', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (222, 85, 'user', '赋属性工具中编辑原点的功能有什么作用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:03', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (223, 85, 'assistant', '**编辑原点功能**用于检查并修改单个或批量工件的坐标原点位置，是确保后续出图、加工及属性赋值准确性的关键前置操作。\n\n典型应用场景包括：  \n1. **批量校准坯料定位**：勾选“检查原点”后显示所有坯料框，统一调整多个工件原点至设计要求位置；  \n2. **适配不同建模习惯**：支持将原点设为四面分中或左下角，满足长条形（如长宽比10:1）等特殊工件的定位规则；  \n3. **保障属性写入准确性**：原点位置直接影响零件编号、长宽高、重量等属性的计算与标注，是「赋属性工具」生成建模档实体属性的前提。\n\n该功能属于「赋属性工具」的核心子功能，必须严格按“勾选检查原点→选择工件→修改位置→应用更新→确定”顺序执行。（参考: 赋属性工具-feature_detail）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.27905914},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.25713286},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_detail\",\"score\":0.835248},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7581718}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:09', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (224, 86, 'user', '赋属性工具中编辑原点的功能有什么作用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:10', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (225, 86, 'assistant', '**编辑原点功能**用于检查并修改单个或批量工件的坐标原点位置，是确保后续出图、加工及属性赋值准确性的关键前置操作。\n\n典型应用场景包括：  \n1. **批量校准坯料定位**：勾选“检查原点”后显示所有坯料框，统一调整多个工件原点至设计要求位置；  \n2. **适配不同建模习惯**：支持将原点设为四面分中或左下角，满足长条形（如长宽比10:1）等特殊工件的定位规则；  \n3. **保障属性写入准确性**：原点位置直接影响零件编号、长宽高、重量等属性的计算与标注，是「赋属性工具」生成建模档实体属性的前提。\n\n该功能属于「赋属性工具」的核心子功能，必须严格按“勾选检查原点→选择工件→修改位置→应用更新→确定”顺序执行。（参考: 赋属性工具-feature_detail）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.27905914},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.25713286},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_detail\",\"score\":0.835248},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7581718}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:17', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (226, 87, 'user', '出图的前置条件是什么？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:17', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (227, 87, 'assistant', '「出图预设」是用于设置出图标准与公共信息（如客户、模号）的功能，支撑公共信息自动关联出图及导BOM。\n\n其关键前置条件为：  \n1. **必须先通过「出图预设」完成“选择用户标准”**；  \n2. 之后才能填写对应标准下的公共信息（字段由基本属性配置表动态加载）；  \n3. 若未选标准，后续操作（如快速涂色）将被阻断，并弹出错误提示。\n\n该功能是「快速涂色」「自动出图」「BOM导出」等操作的必要前提，确保所有出图行为符合统一标准。（参考: 出图预设 - prerequisite）', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/02d6015ef25d4cf78c35eaf49a44fd91.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37094852},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3303719},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.78948605},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.75693196},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.671205}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:22', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (228, 88, 'user', '出图的前置条件是什么？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:22', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (229, 88, 'assistant', '「出图预设」是智一系统中用于统一设置出图标准与公共信息（如客户、模号）的功能，支撑公共信息自动关联出图及BOM导出。\n\n其核心前置条件为：  \n1. **必须先执行「出图预设」中的“选择用户标准”**；  \n2. 仅在选定标准后，系统才能加载对应的基本属性配置表，进而支持填写有效的公共信息；  \n3. 若未完成该步骤，后续操作（如快速涂色）将被拦截并弹出错误提示。\n\n该功能是「快速涂色」「自动出图」「BOM导出」等操作的基础依赖。(参考: 出图预设 - prerequisite)', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/02d6015ef25d4cf78c35eaf49a44fd91.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37094852},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3303719},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.78948605},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.75693196},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.671205}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:27', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (230, 89, 'user', '出图的前置条件是什么？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:27', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (231, 89, 'assistant', '「出图预设」是智一系统中用于统一设置出图标准与公共信息（如客户、模号等）的功能，支撑公共信息自动关联出图及BOM导出。\n\n其核心前置条件为：  \n1. **必须先完成“选择用户标准”**——这是执行快速涂色等后续操作的前提；  \n2. **标准选定后，才能动态加载对应的基本属性配置表**，进而填写该标准下允许的公共信息字段；  \n3. 若跳过此步，系统将弹出错误提示，且无法继续执行快速涂色等依赖操作。\n\n该功能是「快速涂色」「BOM导出」等出图相关操作的基础依赖。(参考: 出图预设 - prerequisite)', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/02d6015ef25d4cf78c35eaf49a44fd91.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37094852},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3303719},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.78948605},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.75693196},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.671205}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:32', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (232, 90, 'user', '为什么导出的图没有注解？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:32', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (233, 90, 'assistant', '您遇到的问题是：**导出的图纸中缺少注解（如英文注解、槽注解等）**。\n\n可能原因及解决步骤如下：\n\n1. **未在配置表中正确设置注解选项**  \n   - 建模出图工具的注解参数（如“英文注解”“槽注解”）需提前在**基本属性工作表**中勾选并保存，**不能在出图界面临时设置**。  \n   - ✅ 解决：打开配置表 → 进入“基本属性”工作表 → 勾选所需注解项 → 保存 → 再执行出图。\n\n2. **勾选了冲突选项导致注解被抑制**  \n   - 例如启用“英制牙”时，系统可能自动切换单位制，部分注解逻辑被跳过（隐含约束）。  \n   - ✅ 解决：对照《模具出图规范》逐项核对，禁用不兼容组合。\n\n3. **使用了旧配置或默认值**  \n   - 若跳过配置表修改直接出图，将沿用旧值或默认值（默认通常不启用注解）。  \n\n📌 **后续注意**：所有工艺标记类选项均需出图前在配置表中显式设定，不可凭印象操作。（参考: 建模出图工具 - caution & dependency）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43698773},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.40168068},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:41', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (234, 91, 'user', '为什么导出的图没有注解？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:41', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (235, 91, 'assistant', '您遇到的问题是：**导出的图纸中缺少注解（如英文注解、槽注解等）**。\n\n可能原因及解决步骤如下：\n\n1. **未在配置表中正确设置注解选项**  \n   - 建模出图工具的注解参数（如“英文注解”“槽注解”）需提前在**基本属性工作表**中勾选并保存，**不能在出图界面临时设置**。  \n   - ✅ 解决：打开配置表 → 进入“基本属性”工作表 → 勾选所需注解项 → 保存 → 再执行出图。\n\n2. **跳过配置表修改，直接出图**  \n   - 若未打开配置表修改，系统将使用旧值或默认值（可能全为未勾选），导致注解不生效。  \n   - ✅ 解决：严格按顺序操作：**打开配置表 → 修改基本属性 → 执行出图**。\n\n3. **勾选项存在隐含约束（如与其他选项冲突）**  \n   - 例如启用“英制牙”可能导致部分单位切换，间接影响注解显示逻辑。  \n   - ✅ 解决：对照《模具出图规范》逐项核对，尤其关注客户特殊要求。\n\n📌 **后续注意事项**：所有工艺标记类选项均需出图前在配置表中确认，不可凭印象操作。（参考: 建模出图工具 - caution & dependency）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43698773},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.40168068},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:49', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (236, 92, 'user', '为什么导出的图没有注解？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:50', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (237, 92, 'assistant', '您遇到的问题是：**导出的图纸中缺少注解（如英文注解、槽注解等）**。\n\n可能原因及解决步骤如下：\n\n1. **未在配置表中正确启用注解选项**  \n   - 建模出图工具的“英文注解”“槽注解”等选项需**提前在配置表的「基本属性工作表」中勾选并保存**，而非在出图界面临时设置。  \n   - ✅ 正确操作：打开配置表 → 进入「基本属性」工作表 → 勾选所需注解项 → 保存 → 再执行出图。\n\n2. **跳过配置表修改，直接出图**  \n   - 若未打开配置表修改，系统将使用旧值或默认值（通常默认关闭注解），导致导出无注解。  \n   - ✅ 补救：重新打开配置表，确认并启用对应注解项后重发出图。\n\n3. **选项间存在隐含约束（如“英制牙”启用影响单位）**  \n   - 某些勾选项会联动改变其他参数，可能导致注解未按预期显示。建议对照《模具出图规范》核对组合逻辑。\n\n📌 **后续注意**：所有工艺标记类选项均需出图前在配置表中确认，不可凭印象操作。（参考: 建模出图工具-caution）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43698773},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.40168068},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087}]', NULL, NULL, NULL, NULL, '2026-05-20 14:21:58', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (238, 93, 'user', '备料板尺寸的大小是否会随前距、后距、左距、右距的值变化而产生变化？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:21:58', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (239, 93, 'assistant', '是的，**备料板尺寸的大小会随前距、后距、左距、右距的值变化而变化**。\n\n这是「建模档合并订料」功能中的关键机制，具体表现为：\n1. **共同决定最终尺寸**：前距、后距、左距、右距等参数协同影响备料板的长宽高；\n2. **影响超限判断**：若单独调整某一距离而忽略其余，可能导致外形尺寸估算失真，触发错误的“超限”提示；\n3. **影响备料数量**：尺寸估算偏差会进一步导致备料数量误判，影响实际生产备料准确性。\n\n该功能属于「建模档合并订料」的核心控制逻辑，与「行距/列距/上距/下距」等其他间距参数共同构成完整的备料板尺寸调控体系。(参考: 建模档合并订料 - caution)', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c227c756052c42a09bcbc34f9fd67e02.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/78aa466378be4cb498660f1a76541905.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/3fca5c3984c1462a8f7a288f4db67089.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f53dbd52e7cd4d2b8ecc90b9e88c732d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ff6dca94663145e8b4ac870c07011a30.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4733348413e4496dad66233b69210d6c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.27148286},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.26537177},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7716138},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.71892637}]', NULL, NULL, NULL, NULL, '2026-05-20 14:22:06', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (240, 94, 'user', '备料板尺寸的大小是否会随前距、后距、左距、右距的值变化而产生变化？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:22:06', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (241, 94, 'assistant', '是的，**备料板尺寸的大小会随前距、后距、左距、右距的值变化而变化**。\n\n这是「建模档合并订料」功能中的关键机制，具体表现为：\n1. **共同决定最终尺寸**：前距、后距、左距、右距等参数协同影响备料板的长、宽、高；\n2. **影响超限判断**：若仅调整单个距离参数而忽略其他，可能导致外形尺寸估算失真，误判是否超出机床加工行程；\n3. **影响备料数量**：尺寸偏差会进一步导致备料数量计算错误，影响实际生产。\n\n该功能属于「建模档合并订料」的核心控制逻辑，与「行距/列距/上距/下距」等间距参数共同构成完整的备料板尺寸调控体系。（参考: 建模档合并订料 - feature_detail）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c227c756052c42a09bcbc34f9fd67e02.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/78aa466378be4cb498660f1a76541905.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/3fca5c3984c1462a8f7a288f4db67089.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f53dbd52e7cd4d2b8ecc90b9e88c732d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ff6dca94663145e8b4ac870c07011a30.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4733348413e4496dad66233b69210d6c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.27148286},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.26537177},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7716138},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.71892637}]', NULL, NULL, NULL, NULL, '2026-05-20 14:22:13', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (242, 95, 'user', '备料板尺寸的大小是否会随前距、后距、左距、右距的值变化而产生变化？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:22:13', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (243, 95, 'assistant', '是的，**备料板尺寸的大小会随前距、后距、左距、右距的值变化而变化**。\n\n这是「建模档合并订料」功能中的关键机制，具体表现为：\n1. **动态影响备料板长宽高**：四个距离参数共同参与备料板最终尺寸计算；\n2. **关联外形尺寸超限判断**：若参数设置不当，可能导致系统误判工件是否超出加工行程；\n3. **影响备料数量估算**：单个参数调整未协同其他参数时，易造成备料数量误判。\n\n该功能属于「建模档合并订料」核心操作环节，与「行距/列距/上距/下距」等间距参数协同作用，共同决定备料板布局与尺寸。（参考: 建模档合并订料 - feature_detail）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c227c756052c42a09bcbc34f9fd67e02.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/78aa466378be4cb498660f1a76541905.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/3fca5c3984c1462a8f7a288f4db67089.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f53dbd52e7cd4d2b8ecc90b9e88c732d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ff6dca94663145e8b4ac870c07011a30.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.27148286},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.26537177},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7716138},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.71892637}]', NULL, NULL, NULL, NULL, '2026-05-20 14:22:21', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (244, 96, 'user', '如何使用赋属性这个功能？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:22:21', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (245, 96, 'assistant', '以下是使用「赋属性工具」的完整操作步骤：\n\n1. **选择写入属性及客户标准**  \n   在工具界面顶部，选择需写入的属性项（如零件编号、长宽高、材质等），并**确认客户标准**（注意用户标准选择）。\n\n2. **选择零件**  \n   支持框选工件，或点击「按配置表全选工件」；若勾选「扫描」，则自动识别已排序工件。\n\n3. **设置零件编码排序**  \n   检查客户标准要求，确保排序逻辑一致（如按图号、尺寸或工艺顺序）。\n\n4. **设定主视图方向**  \n   根据模具类型，**勾选上模/下模的俯视图或仰视图**，用于后续出图基准。\n\n5. **配置原点方向规则**  \n   - 默认以长直边+短直边为零边（长度≥400mm视为大板）；  \n   - 可勾选「规则1」指定涂色边为零边（3D模型需提前涂色）；  \n   - 或勾选「规则2」自定义长宽比（如10:1）及原点位置（四面分中/左下角）。\n\n6. **执行编辑或添加余量（如需）**  \n   - 先勾选「检查原点」→ 显示坯料框 → 选择工件 → 修改原点；  \n   - 或勾选「检查余量」→ 选择工件 → 输入余量值；  \n   - **每步修改后必须点击「应用更新」，再点击「确定」**，否则不生效。（参考: 赋属性工具-operation_guide）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3584834},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35214302},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8652982},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7550333}]', NULL, NULL, NULL, NULL, '2026-05-20 14:22:31', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (246, 97, 'user', '如何使用赋属性这个功能？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:22:32', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (247, 97, 'assistant', '以下是「赋属性工具」的操作步骤：\n\n1. **选择写入属性及客户标准**  \n   在工具界面顶部选择需写入的属性（如零件编号、长宽高、材质等）和对应**客户标准**，注意正确选择用户标准。\n\n2. **选择零件**  \n   可**框选工件**，或点击「扫描」自动识别并排序已加载工件。\n\n3. **设置零件编码排序**  \n   检查客户标准要求，确认编号逻辑（如按位置、尺寸或配置表顺序）。\n\n4. **设定主视图方向**  \n   根据模具类型，选择上模/下模的**俯视图或仰视图**。\n\n5. **配置原点方向规则**  \n   - 默认以长直边+短直边为零边；长度＞400视为大板（可自定义分界值）；  \n   - 勾选「规则1」：指定颜色为零边（3D模型需提前涂色）；  \n   - 勾选「规则2」：自定义长宽比（如10:1识别长条形），并设置原点为四面分中或左下角。\n\n6. **执行关键操作（如编辑原点/添加余量）时**：  \n   必须严格按顺序点击 → **「应用更新」→ 「确定」**，否则修改不生效。（参考: 赋属性工具-operation_guide）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3584834},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35214302},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8652982},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7550333}]', NULL, NULL, NULL, NULL, '2026-05-20 14:22:40', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (248, 98, 'user', '如何使用赋属性这个功能？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:22:40', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (249, 98, 'assistant', '以下是「赋属性工具」的操作步骤：\n\n1. **选择写入属性及客户标准**  \n   在工具界面顶部选择需写入的属性（如零件编号、长宽高、材质等）和对应**客户标准**，注意确认用户标准是否正确。\n\n2. **选择零件**  \n   可**框选工件**，或点击「扫描」自动识别已排序工件；也可按配置表**全选工件**。\n\n3. **设置零件编码排序与主视图方向**  \n   检查客户标准要求；选择上模/下模的**俯视图或仰视图**。\n\n4. **设置原点方向规则**  \n   - 默认以长直边+短直边为零边，长度≥400视为大板；  \n   - 勾选「规则1」：指定某颜色为零边（3D模型需提前涂色）；  \n   - 勾选「规则2」：自定义长宽比（如10:1），并设原点为四面分中或左下角。\n\n5. **执行编辑类操作（如编辑原点、添加余量）时务必**：  \n   先勾选「检查原点」→ 选择工件 → 修改参数 → 点击**应用更新** → 再点击**确定**。（缺一不可）\n\n（参考: 赋属性工具-operation_guide）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3584834},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35214302},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8652982},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7550333}]', NULL, NULL, NULL, NULL, '2026-05-20 14:22:49', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (250, 99, 'user', '如何使用BOM表工具这个功能？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:22:49', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (251, 99, 'assistant', '以下是使用BOM表工具的操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：如“已备料不出料单”“是否分页”，并设置**分页类型和行数**（注意：分页行数不可超过原表格最大行数，如20，否则会导致乱码）  \n4. **扫描BOM表**：可扫描整个图档，或手动**选择实体生成**BOM数据（此为导出前提，无扫描则导出为空或报错）  \n5. **点击“导出EXCEL”**；导出后如需，可进一步点击**EXCEL转TXT文本**\n\n（参考:BOM工具-operation_guide）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.56506085},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3302302},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32617375},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8322726},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.717364}]', NULL, NULL, NULL, NULL, '2026-05-20 14:22:54', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (252, 100, 'user', '如何使用BOM表工具这个功能？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:22:55', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (253, 100, 'assistant', '以下是使用BOM表工具的操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：如“已备料不出料单”“是否分页”，并设置**分页类型和行数**（注意：分页行数不可超过原表格最大行数，如20，否则会导致乱码）  \n4. **生成BOM数据源**：扫描整个图档或**选择实体生成**（此步为导出前提，未执行则导出为空或报错）  \n5. **点击“导出EXCEL”**；导出后如需，可进一步点击“EXCEL转TXT文本”\n\n前置条件：确保已完成图档扫描或实体选择，否则无法导出有效内容。(参考: BOM工具-operation_guide)', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.56506085},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3302302},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32617375},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8322726},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.717364}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:00', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (254, 101, 'user', '如何使用BOM表工具这个功能？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:01', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (255, 101, 'assistant', '以下是使用BOM表工具的操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**（前置条件：确保信息准确）  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：如“已备料不出料单”“是否分页”，并设置**分页类型和行数**（注意：分页行数不可超过原表格最大行数，如20，否则会导致乱码）  \n4. **扫描所有实体生成BOM表**（或手动选择实体生成）——此为导出前提，未扫描则导出为空或报错  \n5. **点击“导出EXCEL”**；导出后如需，可进一步点击“EXCEL转TXT文本”\n\n所有清单（材料/标准件/成本预算）操作方式一致。（参考:BOM工具-operation_guide）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.56506085},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3302302},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32617375},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8322726},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.717364}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:06', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (256, 102, 'user', '如何使用建模出图工具这个功能？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:07', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (257, 102, 'assistant', '以下是使用「建模出图工具」的操作步骤：\n\n1. **前置条件**：先**打开配置表**（含基本属性工作表），在其中修改模具编号、球标大小、加工说明等参数（文档强调“打开基本属性表可修改”）；  \n2. 填写**模具编号**（依赖配置表已打开）；  \n3. 选择要出图的零件类型：**常规出图零件** 或 **轻量化出图零件**；  \n4. 选择投影视角：**第一视角** 或 **第三视角**（决定后续视图方向）；  \n5. 设置视图及符号：勾选需投影的视图（默认主/右/前视图）、**球标图**、**线割涂色**、**研磨符号**；  \n6. 配置图纸信息：设置球标大小、勾选**加工说明**/**英文注解**/**英制牙**、选择做深/掏留、槽注解；  \n7. **填写图纸路径**（必须在所有参数设定完毕后指定）；  \n8. 点击**确定**执行出图，完成后前往指定路径查看图纸。\n\n(参考: 建模出图工具-operation_guide)', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/cae11a9be14d4c6d8093040d8705b7c1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35652167},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.31158954},{\"featureName\":\"建模出图工具\",\"chunkType\":\"operation_guide\",\"score\":0.9246347},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78007317}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:14', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (258, 103, 'user', '如何使用建模出图工具这个功能？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:14', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (259, 103, 'assistant', '以下是使用「建模出图工具」的操作步骤：\n\n1. **前置条件**：先**打开配置表**（含基本属性工作表），在其中修改模具编号、球标大小、加工说明等参数（文档强调“打开基本属性表可修改”）；  \n2. 填写**模具编号**（依赖配置表已打开）；  \n3. 选择要出图的零件类型：**常规出图零件** 或 **轻量化出图零件**；  \n4. 选择投影视角：**第一视角** 或 **第三视角**（决定后续视图方向）；  \n5. 勾选所需视图及符号：主/右/前视图、**球标图**、**线割涂色**、**研磨符号**；  \n6. 设置**球标大小**，按需勾选**加工说明**、**英文注解**、**英制牙**，选择**做深/掏留**、**槽注解**；  \n7. **填写图纸路径**（必须在所有参数设定完毕后指定）；  \n8. 点击**确定**执行出图，完成后前往图纸路径查看结果。\n\n(参考: 建模出图工具-operation_guide)', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/cae11a9be14d4c6d8093040d8705b7c1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35652167},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.31158954},{\"featureName\":\"建模出图工具\",\"chunkType\":\"operation_guide\",\"score\":0.9246347},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78007317}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:21', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (260, 104, 'user', '如何使用建模出图工具这个功能？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:22', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (261, 104, 'assistant', '以下是使用「建模出图工具」的操作步骤：\n\n1. **前置条件**：先**打开配置表**（含基本属性工作表），在其中修改模具编号、球标大小、加工说明等参数（文档强调“打开基本属性表可修改”）；  \n2. 填写**模具编号**（依赖配置表已打开）；  \n3. 选择要出图的零件类型：**常规出图零件** 或 **轻量化出图零件**；  \n4. 选择投影视角：**第一视角** 或 **第三视角**（决定后续视图方向）；  \n5. 勾选所需视图及符号：主/右/前视图、**球标图**、**线割涂色**、**研磨符号**；  \n6. 设置**球标大小**，按需勾选**加工说明**、**英文注解**、**英制牙**，选择**做深/掏留**、**槽注解**；  \n7. **填写图纸路径**（必须在所有参数设定完毕后指定）；  \n8. 点击**确定**执行出图，完成后前往指定路径查看图纸。  \n（参考:建模出图工具-operation_guide）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/cae11a9be14d4c6d8093040d8705b7c1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35652167},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.31158954},{\"featureName\":\"建模出图工具\",\"chunkType\":\"operation_guide\",\"score\":0.9246347},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78007317}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:29', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (262, 105, 'user', '如何使用快速涂色赋注解这个功能？', '快速涂色赋注解', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:30', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (263, 105, 'assistant', '以下是使用「快速涂色赋注解」功能的完整操作指引：\n\n前置条件：**必须先设置建模档出图标准**，否则工件分析功能不可用。\n\n1. **选择设计标准**  \n　　在工具主界面点击「选择设计标准」，根据客户要求选定对应标准（如启泰标准）。\n\n2. **打开工件分析**  \n　　点击「工件分析」→ 框选需处理的多个实体 → 设置“大板是否注解槽”等参数 → 点击分析，生成孔识别结果与待处理列表。\n\n3. **上色**  \n　　在「材质颜色（体色）」中选择对应材质色 → 弹出「选择实体」对话框 → 选中目标实体完成上色；  \n　　或勾选「选择涂色」→ 在「加工颜色（面色）」中选色 → 弹出「选择面」对话框 → 选面涂色。\n\n4. **修改/添加注解**  \n　　在分析结果列表中检查并修改已有注解；  \n　　也可**选面后点击“注释”按钮**→ 在弹出文本框中输入内容，**按回车确认**。\n\n（参考: 快速涂色赋注解-operation_guide）', '快速涂色赋注解', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/1ad500d9a8634e38a4ab0015bc0efdbd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35740045},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.33634752},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"operation_guide\",\"score\":0.93259734},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (264, 106, 'user', '如何使用快速涂色赋注解这个功能？', '快速涂色赋注解', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (265, 106, 'assistant', '以下是使用「快速涂色赋注解」功能的操作步骤：\n\n1. **前置条件：设置设计标准**  \n   进入【建模档出图标准设置】，选择适用的设计标准（如启泰标准）；未设置则分析功能不可用，会弹出提示。\n\n2. **工件分析**  \n   点击【工件分析】→ 框选多个实体 → 设置“大板是否注解槽”等参数 → 开始分析，生成孔识别结果与待处理列表。\n\n3. **上色**  \n   在【材质颜色（体色）】中选择材质对应颜色 → 弹出“选择实体”对话框 → 选中需上色的体完成涂色；注意：除“任意色”外，色号须通过【材质颜色表】配置修改。\n\n4. **赋注解**  \n   - 自动注解：基于分析结果，在下方列表检查/修改孔的注释；  \n   - 手动添加：点击【特征注解表】→ 选面→点击“注释”→在文本框编辑内容，**按回车确认**。\n\n（参考: 快速涂色赋注解-operation_guide）', '快速涂色赋注解', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/1ad500d9a8634e38a4ab0015bc0efdbd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35740045},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.33634752},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"operation_guide\",\"score\":0.93259734},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (266, 107, 'user', '如何使用快速涂色赋注解这个功能？', '快速涂色赋注解', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:45', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (267, 107, 'assistant', '以下是使用「快速涂色赋注解」功能的操作步骤：\n\n1. **前置条件：设置设计标准**  \n   进入【建模档出图标准设置】，选择适用的设计标准（如启泰标准）；未设置则分析功能不可用，且会弹出提示。\n\n2. **打开工件分析**  \n   点击【工件分析】→ 框选需处理的多个实体 → 设置参数（如大板是否注解槽、单位制式等）→ 执行分析，生成孔识别结果与待处理列表。\n\n3. **上色**  \n   在【材质颜色（体色）】中选择对应材质颜色 → 弹出“选择实体”对话框 → 选中目标实体完成上色。\n\n4. **赋注解**  \n   - 在分析结果列表中检查/修改已有注释；  \n   - 或点击【特征注解表】→ 【打开配置表】配置参数；  \n   - 也可手动选面添加注解：点击“选面添加注解”→ 在文本框中编辑内容，**按回车确认**。\n\n（参考: 快速涂色赋注解-operation_guide）', '快速涂色赋注解', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/1ad500d9a8634e38a4ab0015bc0efdbd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35740045},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.33634752},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"operation_guide\",\"score\":0.93259734},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:52', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (268, 108, 'user', '赋属性工具中编辑原点的功能如何使用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:52', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (269, 108, 'assistant', '(参考:赋属性工具-operation_guide)\n\n编辑原点功能需严格按以下步骤操作：\n\n前置条件：必须先勾选「检查原点」，否则无法显示坯料框，无法选择工件。\n\n1. **勾选「检查原点」**  \n   在赋属性工具界面中找到并勾选该选项，系统将显示所有坯料框。\n\n2. **选择单个或多个工件**  \n   在已显示的坯料框中，点击选择目标工件（支持多选）。\n\n3. **修改原点位置**  \n   在弹出的编辑面板中，调整原点坐标或拖动至目标位置。\n\n4. **点击「应用更新」**  \n   此步为关键，不点击则修改不生效。\n\n5. **点击「确定」**  \n   完成持久化保存，使修改正式生效。\n\n注意：跳过任一环节（如未勾选、未应用、未确定）均会导致操作无效。(参考:赋属性工具-prerequisite)', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.28229034},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.26576188},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8726206},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.76713276}]', NULL, NULL, NULL, NULL, '2026-05-20 14:23:58', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (270, 109, 'user', '赋属性工具中编辑原点的功能如何使用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:23:58', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (271, 109, 'assistant', '(参考:赋属性工具-operation_guide)\n\n编辑原点功能用于修改单个或多个工件的原点位置，需严格按顺序操作：\n\n前置条件：必须先勾选「检查原点」，否则无法显示坯料框，无法选择工件。\n\n1. **勾选「检查原点」**  \n   → 在工具界面找到并勾选该选项，使所有坯料框可见；\n\n2. **选择工件**  \n   → 单击或框选需修改原点的一个或多个工件；\n\n3. **修改原点位置**  \n   → 在弹出设置中调整原点坐标（如左下角、四面分中等）；\n\n4. **点击「应用更新」**  \n   → 使修改实时生效（跳过此步则不生效）；\n\n5. **点击「确定」**  \n   → 完成持久化保存。\n\n注意：若需按颜色识别零边，请提前在「主视图方向」中勾选规则1并完成3D涂色。(参考:赋属性工具- operation_guide)', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.28229034},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.26576188},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8726206},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.76713276}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:04', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (272, 110, 'user', '赋属性工具中编辑原点的功能如何使用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:05', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (273, 110, 'assistant', '以下是「赋属性工具」中**编辑原点**功能的使用步骤：\n\n前置条件：必须先勾选**检查原点**，否则无法显示坯料框，无法选择工件。\n\n1. **勾选「检查原点」**  \n   在工具界面找到并勾选该选项，使所有坯料框显示出来。\n\n2. **选择工件**  \n   单击或框选一个/多个需修改原点的工件。\n\n3. **修改原点位置**  \n   在弹出的设置区域中，调整原点坐标或方向（如四面分中、左下角等）。\n\n4. **点击「应用更新」**  \n   此步为关键，不点击则修改不生效。\n\n5. **点击「确定」**  \n   完成操作，使修改持久化保存。\n\n（参考: 赋属性工具-operation_guide）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.28229034},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.26576188},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8726206},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.76713276}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:10', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (274, 111, 'user', '如何使用建模档合并订料的删除实体功能？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (275, 111, 'assistant', '1. 在「建模档合并订料」功能界面中，找到并**单击“删除实体”按钮**；  \n2. 弹出“选择需要移除的实体”UI对话框；  \n3. 在对话框中**勾选需要删除的目标实体**，确认移除。  \n\n前置条件：确保所选实体尚未完成备料（已备料实体无法被选中）；建议先启用「隐藏已备料」功能，以便清晰筛选未备料对象。(参考:建模档合并订料-feature_detail)', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5bfd74da2d7147fc8acd601e4f1d3b1c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/db20955408c14f1088771357cb22e63c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.6429899},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35099238},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.83861476},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7376036}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:14', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (276, 112, 'user', '如何使用建模档合并订料的删除实体功能？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:15', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (277, 112, 'assistant', '1. 在「建模档合并订料」功能界面中，找到并**单击“删除实体”按钮**；  \n2. 弹出“选择需要移除的实体”UI对话框；  \n3. 在对话框中**勾选需删除的目标实体**，确认移除。  \n\n前置条件：确保所选实体尚未完成备料（已备料实体无法被选中）；建议先启用「隐藏已备料」功能，以便清晰筛选未备料对象。(参考: 建模档合并订料-feature_detail)', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5bfd74da2d7147fc8acd601e4f1d3b1c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/db20955408c14f1088771357cb22e63c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.6429899},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35099238},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.83861476},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7376036}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:19', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (278, 113, 'user', '如何使用建模档合并订料的删除实体功能？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:19', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (279, 113, 'assistant', '1. 在「建模档合并订料」功能界面中，找到并**单击“删除实体”按钮**；  \n2. 弹出“选择需要移除的实体”UI对话框；  \n3. 在对话框中**勾选需要删除的目标实体**，确认移除。  \n\n前置条件：确保所选实体尚未完成备料（已备料实体无法被选中）；建议配合使用「隐藏已备料」功能，以便清晰筛选未备料对象。(参考: 建模档合并订料-feature_detail)', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5bfd74da2d7147fc8acd601e4f1d3b1c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/db20955408c14f1088771357cb22e63c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.6429899},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35099238},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.83861476},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7376036}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:23', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (280, 114, 'user', '快速涂色功能具体如何使用？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (281, 114, 'assistant', '以下是「快速涂色」功能的完整操作指引：\n\n前置条件：**必须先选择设计标准**（如启泰品牌标准），否则会提示“找不到配置表”。\n\n1. **打开配置表**  \n　　- 选择“特征注解表”或“材质颜色表” → 单击**“打开配置表”**，完成特征/颜色参数配置。\n\n2. **设置涂色范围**  \n　　- 勾选**“选择涂色”**；  \n　　- 勾选需上色的**面或体所在图层**。\n\n3. **指定颜色**  \n　　- 在**“加工颜色（面色）”**中选择颜色 → 弹出“选择面”对话框 → 手动选取目标面；  \n　　- 在**“材质颜色（体色）”**中选择颜色 → 弹出“选择实体”对话框 → 手动选取目标体。  \n　　⚠️ 注意：除“任意色”外，其他颜色需通过配置表修改色号。\n\n（参考: 快速涂色-feature_detail）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7437954},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.34567127},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.80918795},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.8011743},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7945772}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:30', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (282, 115, 'user', '快速涂色功能具体如何使用？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:30', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (283, 115, 'assistant', '以下是「快速涂色」功能的完整操作指引：\n\n前置条件：**必须先选择设计标准**（如启泰品牌标准），否则会提示“找不到配置表”。\n\n1. **打开配置表**  \n　　→ 选择“特征注解表”或“材质颜色表”；  \n　　→ 单击**“打开配置表”**，对特征参数或材质颜色进行配置。\n\n2. **设置涂色范围**  \n　　→ 勾选**“选择涂色”**；  \n　　→ 勾选需上色的**面/体所在图层**。\n\n3. **执行涂色**  \n　　→ 在**“加工颜色（面色）”**中选色 → 弹出“选择面”对话框 → 手动选取面；  \n　　→ 在**“材质颜色（体色）”**中选色 → 弹出“选择实体”对话框 → 手动选取体。  \n　　⚠️ 注意：除“任意色”外，其他颜色需通过配置表修改色号。\n\n（参考: 快速涂色-feature_detail）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7437954},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.34567127},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.80918795},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.8011743},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7945772}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (284, 116, 'user', '快速涂色功能具体如何使用？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (285, 116, 'assistant', '以下是「快速涂色」功能的完整操作指引：\n\n前置条件：**必须先选择设计标准**（如启泰品牌标准），否则会提示“找不到配置表”。\n\n1. **打开配置表**  \n　　- 选择“特征注解表”或“材质颜色表” → 单击**“打开配置表”**，完成特征、图层、材质类型及颜色参数配置。\n\n2. **设置涂色范围**  \n　　- 勾选**“选择涂色”**；  \n　　- 勾选需上色的面/体所在**图层**。\n\n3. **执行涂色**  \n　　- 在**“加工颜色（面色）”**中选色 → 弹出“选择面”对话框 → 手动选取目标面；  \n　　- 在**“材质颜色（体色）”**中选色 → 弹出“选择实体”对话框 → 手动选取目标体。  \n　　⚠️ 注意：除“任意色”外，其他颜色需通过配置表修改色号。\n\n（参考: 快速涂色-feature_detail）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7437954},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.34567127},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.80918795},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.8011743},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7945772}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (286, 117, 'user', '建模出图工具是做什么用的？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (287, 117, 'assistant', '智一「建模出图工具」是用于将3D建模档自动导出为2D工程图的专用功能。\n\n典型应用场景包括：  \n1. **常规零件出图**：快速生成主视图、右视图、前视图等标准投影视图；  \n2. **轻量化出图**：针对结构简单零件，输出精简版2D图以提升效率；  \n3. **符号与注解配置**：支持线割涂色（默认红色186）、球标图、研磨符号、加工说明、英文注解等工艺标注。\n\n该工具依赖「配置表」和「基本属性表」，需按顺序完成模具编号填写、视角选择、视图设置等步骤，是建模后标准化出图流程的关键环节。（参考: 建模出图工具-feature_intro）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.30495808},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.25624877},{\"featureName\":\"建模出图工具\",\"chunkType\":\"feature_intro\",\"score\":0.89293945},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"prerequisite\",\"score\":0.7263198}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:50', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (288, 118, 'user', '建模出图工具是做什么用的？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:51', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (289, 118, 'assistant', '智一「建模出图工具」是用于将3D建模文件自动导出为2D工程图纸的专用功能。\n\n典型应用场景包括：  \n1. **常规出图**：为模具零件快速生成标准2D视图（主/右/前视图）；  \n2. **轻量化出图**：针对简化模型生成轻量级2D图纸，提升处理效率；  \n3. **符号与注解配置**：支持线割涂色（默认红色）、球标图、研磨符号、加工说明、英文注解等工艺标注需求。\n\n该工具依赖「配置表」和「基本属性表」，需按顺序完成模具编号填写、视角选择（第一/第三角）、视图设置及图纸路径指定等步骤，是建模到生产图纸流转的关键环节。(参考: 建模出图工具-feature_intro)', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.30495808},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.25624877},{\"featureName\":\"建模出图工具\",\"chunkType\":\"feature_intro\",\"score\":0.89293945},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"prerequisite\",\"score\":0.7263198}]', NULL, NULL, NULL, NULL, '2026-05-20 14:24:57', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (290, 119, 'user', '建模出图工具是做什么用的？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:24:57', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (291, 119, 'assistant', '智一「建模出图工具」是用于将3D建模档自动导出为2D工程图的专用功能。\n\n典型应用场景包括：  \n1. **快速生成标准图纸**：支持一键导出主视图、右视图、前视图等常规投影视图；  \n2. **灵活适配工艺需求**：可选择轻量化零件视图、添加球标图、线割涂色（默认红色186）、研磨符号等；  \n3. **多视角与注解配置**：支持第一/第三视角切换，并可启用加工说明、英文注解、英制牙、槽注解等定制化输出。\n\n该工具依赖「配置表」（含基本属性工作表）作为前置条件，所有参数（如模具编号、视图设置、球标大小、图纸路径）均按严格步骤顺序配置，确保出图规范统一。（参考: 建模出图工具-feature_intro）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.30495808},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.25624877},{\"featureName\":\"建模出图工具\",\"chunkType\":\"feature_intro\",\"score\":0.89293945},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"prerequisite\",\"score\":0.7263198}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:03', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (292, 120, 'user', '零件刻字这个功能主要用户做什么？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:04', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (293, 120, 'assistant', '「零件刻字工具」是智一平台中用于在建模文件完成属性赋值后，**在指定几何面上自动生成带属性信息（如编号、材质、热处理等）的刻字特征**的功能。\n\n典型应用场景包括：  \n1. **非标件标识**：在机加工前于零件平面或圆柱面自动刻印编号、材质等关键属性；  \n2. **正/反向定位刻字**：选择平面左半边正向放置文字，右半边则反向放置，适配装配方向需求；  \n3. **多类型刻字方式**：支持分割面、凹槽、凸起等多种刻字形式，满足不同工艺要求。\n\n该功能依赖前置的“建模档排序赋属性”流程，且必须执行“更新显示”后才生成实际刻字实体，与「属性管理」「建模排序」等功能紧密协同。(参考:零件刻字-feature_intro)', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3525817},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3076044},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.8988741},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:10', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (294, 121, 'user', '零件刻字这个功能主要用户做什么？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:10', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (295, 121, 'assistant', '「零件刻字工具」是智一平台中用于在建模文件完成属性赋值后，**在指定几何面上自动生成带属性信息（如编号、材质、热处理等）的刻字特征**的功能。\n\n典型应用场景包括：  \n1. **非标件标识**：在机加工前于零件平面或圆柱面自动刻印编号、材质等关键属性；  \n2. **正/反向定位刻字**：选择平面左半边正向放置文字，右半边则反向放置，适配装配方向需求；  \n3. **多样化刻字形式**：支持分割面、凹槽、凸起等多种刻字方式，满足不同工艺要求。\n\n该功能依赖前置的“建模档排序赋属性”操作，且必须执行“更新显示”后才能生成实际刻字实体，后续尺寸与位置调整才生效。（参考: 零件刻字 - feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3525817},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3076044},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.8988741},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:16', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (296, 122, 'user', '零件刻字这个功能主要用户做什么？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:16', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (297, 122, 'assistant', '「零件刻字工具」是智一平台中用于在建模档完成属性赋值后，**在指定几何面上自动生成带属性信息（如编号、材质、热处理等）的刻字特征**的功能。\n\n典型应用场景包括：  \n1. **非标件标识**：在零件平面或圆柱面上刻印唯一编号、材质代号，便于生产识别；  \n2. **工艺追溯**：在分割面、凹槽或凸起区域刻写热处理状态，支持质量管控；  \n3. **正/反向适配**：根据选择平面左/右半边自动正置或反置文字，适配装配方向需求。\n\n该功能依赖于前置的「建模档排序与属性赋值」，且必须执行“更新显示”后才生成实际刻字实体，后续尺寸与位置调整才生效。（参考:零件刻字-feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3525817},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3076044},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.8988741},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:22', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (298, 123, 'user', '零刻刻字功能,有几种刻字方式？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:23', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (299, 123, 'assistant', '「零件刻字功能」是智一提供的用于在建模档（已完成排序赋属性）上按指定属性自动刻印文字的工具。\n\n它支持以下**3种刻字方式**：  \n1. **分割面刻字**——在面分割区域上刻字；  \n2. **凹槽刻字**——在凹陷区域中刻字；  \n3. **凸起刻字**——在凸起区域中刻字。\n\n此外，刻字前需先选择**平面或圆柱面**作为载体，并可指定左/右半边以控制正/反放置方向；字高、字宽及宽高比均可自定义，方位限制为旋转面平行方向和四方移动。\n\n该功能依赖于前置的“建模档排序赋属性”流程，且必须执行“更新显示”后刻字实体才真正生成。（参考: 零件刻字 - feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/dd104752e2144e97a3ab7607363af158.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36451617},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.36125597},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.7520205},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:29', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (300, 124, 'user', '零刻刻字功能,有几种刻字方式？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:29', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (301, 124, 'assistant', '「零件刻字工具」是用于在建模档完成属性赋值后，对非标件或标准件进行带属性文字刻印的功能。\n\n它支持以下**3种刻字方式**：  \n1. **分割面刻字**——在模型分割面上生成刻字；  \n2. **凹槽刻字**——在表面开凿凹陷文字；  \n3. **凸起刻字**——在表面生成凸出文字。\n\n该功能依赖于前置步骤（如选择刻字类型、位置），且**只有执行“更新显示”后，刻字才实际生成**，后续尺寸与位置调整才生效。（参考: 零件刻字 - feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/dd104752e2144e97a3ab7607363af158.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36451617},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.36125597},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.7520205},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:34', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (302, 125, 'user', '零刻刻字功能,有几种刻字方式？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:34', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (303, 125, 'assistant', '「零件刻字功能」是智一提供的用于在建模档（已完成排序赋属性）上按指定属性自动刻印文字的工具。\n\n它支持以下**3种刻字方式**：  \n1. **分割面刻字**：在模型已有的分割面上进行刻字；  \n2. **凹槽刻字**：在平面上创建凹陷文字；  \n3. **凸起刻字**：在平面上创建凸出文字。\n\n该功能需严格遵循操作顺序（如先选位置再设属性），且只有执行“更新显示”后，刻字才实际生成，后续尺寸与位置调整才生效。（参考: 零件刻字 - feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/dd104752e2144e97a3ab7607363af158.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36451617},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.36125597},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.7520205},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:41', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (304, 126, 'user', '快速涂色这个功能主要用户做什么？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:41', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (305, 126, 'assistant', '**快速涂色**是智一平台提供的「快速改色工具」，主要用于对建模档中的**体、孔、键槽、面**进行批量颜色切换。\n\n典型应用场景包括：  \n1. **按设计标准统一着色**：根据品牌（如启泰）选择对应设计标准后，批量设置不同特征的图层与材质颜色；  \n2. **精细化颜色配置**：通过“特征注解表”或“材质颜色表”配置参数，实现对特定面（面色）或实体（体色）的颜色控制；  \n3. **手动精准涂色**：勾选“选择涂色”，在指定图层中交互式选取面/体，并关联配置表设定颜色（非“任意色”需经配置表修改色号）。\n\n该功能依赖于**设计标准选择**与**配置表加载**，与其他颜色管理功能（如材质库、图层管理）深度联动。（参考: 快速涂色 - feature_detail）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7039099},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.32448876},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.74883443},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7387168},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7290655}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:48', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (306, 127, 'user', '快速涂色这个功能主要用户做什么？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:48', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (307, 127, 'assistant', '**快速涂色**是智一平台提供的「快速改色工具」，主要用于对建模中的**体、孔、键槽、面**进行批量颜色切换。\n\n典型应用场景包括：\n1. **按设计标准统一着色**：根据品牌（如启泰）选择对应设计标准，自动匹配图层与材质颜色；\n2. **精细化颜色配置**：通过“特征注解表”或“材质颜色表”配置参数，实现结构化上色；\n3. **手动选择性涂色**：勾选目标图层，分别对“面”（加工色）和“体”（材质色）指定颜色，支持过滤与精准替换。\n\n该功能依赖“设计标准”前置设置，未设置时将提示“找不到配置表”，需先完成标准选择。（参考: 快速涂色-feature_detail）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7039099},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.32448876},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.74883443},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7387168},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7290655}]', NULL, NULL, NULL, NULL, '2026-05-20 14:25:53', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (308, 128, 'user', '快速涂色这个功能主要用户做什么？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:25:54', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (309, 128, 'assistant', '**快速涂色**是智一平台的「快速改色工具」，主要用于对建模档中的**体、孔、键槽、面**进行批量颜色切换。\n\n典型应用场景包括：\n1. **按设计标准统一着色**：根据品牌（如启泰）选择对应设计标准，自动匹配图层与材质颜色；\n2. **精细化颜色配置**：通过“特征注解表”或“材质颜色表”配置参数，实现结构化上色；\n3. **手动精准涂色**：勾选“选择涂色”，在指定图层中交互式选取面或实体，并分别设置面色（加工颜色）与体色（材质颜色）。\n\n该功能依赖于“设计标准”前置设置，且除“任意色”外，其他颜色需通过配置表定义色号，与「特征配置」「材质管理」等模块紧密协同。(参考: 快速涂色-feature_detail)', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7039099},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.32448876},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.74883443},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7387168},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7290655}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:00', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (310, 129, 'user', '建模档出图预设功能需要填写哪些公共信息？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:00', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (311, 129, 'assistant', '「建模档出图预设」是用于设置出图标准与公共信息（如客户、模号等）的配置功能，支持公共信息自动关联出图及导BOM。\n\n需填写的公共信息**并非固定**，而是由系统级的「基本属性配置表」动态决定，典型可填字段包括：  \n1. **客户**——用于图纸标题栏和BOM归属标识；  \n2. **模号**——关联模具项目，支撑出图命名与归档；  \n3. 其他字段（如产品名称、设计者、版本号等）是否可用，取决于当前所选用户标准对应的基本属性配置表中是否已启用。\n\n⚠️ 注意：必须**先选择用户标准**，系统才能加载该标准下允许填写的公共信息字段；未选标准则无字段可填或填写无效。（参考: 出图预设 - feature_intro）', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d185b8cecec3455997ea3739bc436f4f.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.4145788},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3500699},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.9618698},{\"featureName\":\"出图预设\",\"chunkType\":\"caution\",\"score\":0.8066035},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.803983}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:06', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (312, 130, 'user', '建模档出图预设功能需要填写哪些公共信息？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:07', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (313, 130, 'assistant', '建模档出图预设功能需填写的公共信息**并非固定**，具体字段由系统配置决定。操作步骤如下：\n\n1. **选择用户标准**（前置条件：必须先完成此步，否则无法加载对应字段）  \n2. 系统根据所选标准，**动态加载“基本属性配置表”中已启用的公共信息字段**  \n\n⚠️ 注意：  \n- “客户”“模号”等常见字段**不一定默认存在**，需确认其已在当前标准对应的基本属性配置表中启用；  \n- 若所需字段缺失，需联系管理员调整配置表，用户无法自行增删。\n\n（参考: 出图预设 - operation_guide）', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b910649ba6e147578475c7ae5468d788.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d185b8cecec3455997ea3739bc436f4f.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.4145788},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3500699},{\"featureName\":\"出图预设\",\"chunkType\":\"operation_guide\",\"score\":0.9547618},{\"featureName\":\"出图预设\",\"chunkType\":\"caution\",\"score\":0.8066035},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.803983}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:12', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (314, 131, 'user', '建模档出图预设功能需要填写哪些公共信息？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:13', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (315, 131, 'assistant', '建模档出图预设功能中，需填写的公共信息**并非固定**，而是由系统配置决定。具体操作如下：\n\n1. **前置条件**：先在「出图预设」界面**选择用户标准**（如启泰标准），系统据此加载对应的基本属性配置表；  \n2. 进入「填写公共信息」步骤，系统**动态显示该标准下已启用的字段**（如客户、模号等）；  \n3. 仅对配置表中已启用的字段进行填写，未启用的字段不会出现，也不可手动添加。\n\n⚠️ 注意：若所需字段（如“客户”）未显示，请联系管理员检查「基本属性配置表」是否已将其配置为该标准下的公共信息项。(参考: 出图预设 - operation_guide)', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b910649ba6e147578475c7ae5468d788.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d185b8cecec3455997ea3739bc436f4f.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.4145788},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3500699},{\"featureName\":\"出图预设\",\"chunkType\":\"operation_guide\",\"score\":0.9547618},{\"featureName\":\"出图预设\",\"chunkType\":\"caution\",\"score\":0.8066035},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.803983}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:18', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (316, 132, 'user', '介绍一下赋属性工具这个功能的作用。', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:19', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (317, 132, 'assistant', '智一「赋属性工具」是为建模档实体批量生成标准化工程属性的专用功能，是出图前的关键准备步骤。\n\n其主要作用包括：\n1. **自动生成核心属性**：可一键写入零件编号、长宽高、材质、热处理、重量、页码等属性；\n2. **支持灵活排序与定位**：按上/下模俯/仰视图选择、颜色标记原点、按尺寸（如长＞400识别为大板）自动分类；\n3. **提供精细化编辑能力**：支持删除全部属性、编辑单个/多个工件原点、添加余量并自定义比例规则。\n\n该工具需配合「删除属性→确认生效→写入属性」的标准流程使用，确保属性状态干净、避免混杂覆盖。（参考: 赋属性工具-feature_intro）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6e633cc34b078c5122d0fe42b074.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32320306},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.31693467},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9166168},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (318, 133, 'user', '介绍一下赋属性工具这个功能的作用。', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (319, 133, 'assistant', '**赋属性工具**是智一平台中用于为建模档实体批量生成和管理关键工程属性的功能，是出图前的必要准备步骤。\n\n典型应用场景包括：\n1. **自动生成零件编号、长宽高、材质、热处理、重量、页码等属性**，满足图纸标准化输出要求；\n2. **按客户标准或用户自定义规则（如长宽比、尺寸阈值）智能排序并设置原点位置**（如四面分中或左下角）；\n3. **支持属性全量删除、原点编辑、余量添加等精细化操作**，确保数据一致性与可追溯性。\n\n该工具需配合「删除属性→确认生效→写入属性」的严格顺序执行，以避免新旧属性混杂。（参考: 赋属性工具-feature_intro）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6e633cc34b078c5122d0fe42b074.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32320306},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.31693467},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9166168},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:29', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (320, 134, 'user', '介绍一下赋属性工具这个功能的作用。', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:29', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (321, 134, 'assistant', '**赋属性工具**是智一平台中用于为建模档实体批量生成并写入关键工程属性的专用功能，是出图前的必要准备步骤。\n\n其典型应用场景包括：\n1. **自动生成零件编号、长宽高、材质、热处理、重量、页码等标准属性**，满足图纸输出规范；\n2. **按客户或企业标准（如上/下模俯仰视图、颜色标记原点）智能排序与赋值**；\n3. **支持删除全部旧属性后重新写入**，确保属性状态干净、避免混杂覆盖。\n\n该工具需严格遵循「删除属性 → 确认生效 → 写入属性」的操作顺序，否则可能导致新旧属性冲突。（参考: 赋属性工具-feature_intro）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6e633cc34b078c5122d0fe42b074.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32320306},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.31693467},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9166168},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:35', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (322, 135, 'user', '介绍一下赋注解属性这个功能的作用。', '赋注解属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:35', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (323, 135, 'assistant', '**赋注解属性工具**是智一平台中用于UG建模档的注解分析、预览与修改的专业功能。\n\n其主要作用包括：  \n1. **分析预览零件注解**：自动识别并展示模型中已有的注解（如沉头孔、槽等），支持按面或工件层级预览；  \n2. **灵活配置注解规则**：可设置沉头孔为“做深”或“掏留”，控制大板是否注解槽，以及统一调整注解图元的字体大小与颜色；  \n3. **辅助人工标注管理**：支持手动添加注解，并与自动分析结果统一管理、展示图元/图层+编号。\n\n该功能依赖“自动分析注解”作为前置步骤，后续的展示与编号动作均基于分析结果展开。（参考: 赋注解属性工具-feature_intro）', '赋注解属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/29dd4267d56446739470d0637f77b837.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36330143},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.32296157},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9079393},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"dependency\",\"score\":0.7847868}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:41', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (324, 136, 'user', '介绍一下赋注解属性这个功能的作用。', '赋注解属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:41', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (325, 136, 'assistant', '**赋注解属性工具**是智一平台中用于UG建模档的注解分析、预览与修改的专业功能。\n\n其主要作用包括：  \n1. **分析预览零件注解**：自动识别并展示模型中已有的注解（如沉头孔、槽等），支持按面或工件层级预览；  \n2. **灵活配置注解规则**：可设置沉头孔为“做深”或“掏留”，控制大板是否注解槽，以及统一调整注解图元的字体大小与颜色；  \n3. **辅助人工标注管理**：支持手动添加注解，并与自动分析结果统一管理、展示于图元/图层+编号视图中。\n\n该功能依赖“选择对象 → 选择注解要求 → 自动分析注解”的线性流程，其中**自动分析是后续所有呈现动作（如图元展示、图层编号）的前提条件**。（参考: 赋注解属性工具-feature_intro）', '赋注解属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/29dd4267d56446739470d0637f77b837.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36330143},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.32296157},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9079393},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"dependency\",\"score\":0.7847868}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:47', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (326, 137, 'user', '介绍一下赋注解属性这个功能的作用。', '赋注解属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:47', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (327, 137, 'assistant', '**赋注解属性工具**是智一平台中用于UG建模档的注解分析、预览与修改的专业功能。\n\n其典型应用场景包括：  \n1. **分析预览零件注解**：快速检查UG模型中已有的尺寸、形位公差等注解信息；  \n2. **按规则修改注解**：如将沉头孔注解设为“做深”或“掏留”，控制大板槽是否注解；  \n3. **统一注解样式管理**：设置图元字体大小、注解颜色，确保图纸输出风格一致。\n\n该功能操作遵循线性流程：**选择对象 → 选择注解要求 → 自动分析注解 →（可选）手动添加 → 展示图元/图层+编号**，其中“自动分析注解”是后续所有呈现动作的前置必要步骤。（参考: 赋注解属性工具-feature_intro）', '赋注解属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/29dd4267d56446739470d0637f77b837.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36330143},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.32296157},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9079393},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"dependency\",\"score\":0.7847868}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:53', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (328, 138, 'user', '建模档合并订料的旋转功能,有几种旋转方式？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:53', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (329, 138, 'assistant', '建模档合并订料的旋转功能提供**2种旋转方式**：  \n1. **左旋90度**：单击按钮后选择对象，在“选择对象”对话框中指定需左旋的工件；  \n2. **右旋90度**：单击按钮后选择对象，在“选择对象”对话框中指定需右旋的工件。  \n\n该功能属于「建模档合并订料」模块下的子功能，主要用于工件空间姿态调整，常配合翻转（左右/上下）与动态调整位置等功能协同使用，以满足备料板排布和加工行程适配需求。(参考: 建模档合并订料-feature_detail)', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f8b384b8517e43d1a054497b2e97374b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0e1b6864a21c4e8da8489c788155b425.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2742fffdec9543f891ff4c4f49ac7ff9.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/37585de86a804a6cb499ca2454f73c25.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/34e06e73701d42b8a9da910897df45e0.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/304f07507ebc413ea5167781955df8fb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9979225fed0646048032d0a289e01989.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.69022626},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.2777597},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.8417509},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.80098265}]', NULL, NULL, NULL, NULL, '2026-05-20 14:26:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (330, 139, 'user', '建模档合并订料的旋转功能,有几种旋转方式？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:26:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (331, 139, 'assistant', '「建模档合并订料」的旋转功能提供**2种旋转方式**：  \n1. **左旋90度**：单击按钮后选择对象，在弹出的“选择对象”对话框中指定需旋转的工件；  \n2. **右旋90度**：操作方式与左旋一致，仅旋转方向相反。  \n\n该功能属于「建模档合并订料」中的子功能，主要用于对已选工件进行快速方位调整，常用于优化排料空间或适配加工方向。它与「左右翻转」「上下翻转」并列，但**旋转不改变工件镜像属性，而翻转会**。（参考: 建模档合并订料-feature_detail）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f8b384b8517e43d1a054497b2e97374b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0e1b6864a21c4e8da8489c788155b425.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2742fffdec9543f891ff4c4f49ac7ff9.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/37585de86a804a6cb499ca2454f73c25.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/34e06e73701d42b8a9da910897df45e0.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/304f07507ebc413ea5167781955df8fb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9979225fed0646048032d0a289e01989.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.69022626},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.2777597},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.8417509},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.80098265}]', NULL, NULL, NULL, NULL, '2026-05-20 14:27:04', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (332, 140, 'user', '建模档合并订料的旋转功能,有几种旋转方式？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-20 14:27:04', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (333, 140, 'assistant', '建模档合并订料的旋转功能提供**2种旋转方式**：  \n1. **左旋90度**：单击对应按钮，选择对象后执行逆时针90°旋转；  \n2. **右旋90度**：单击对应按钮，选择对象后执行顺时针90°旋转。  \n\n此外，该功能还支持**翻转操作**（左右翻转、上下翻转），但严格意义上的“旋转”仅指上述两种90度方向旋转。（参考: 建模档合并订料-feature_detail）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f8b384b8517e43d1a054497b2e97374b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0e1b6864a21c4e8da8489c788155b425.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2742fffdec9543f891ff4c4f49ac7ff9.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/37585de86a804a6cb499ca2454f73c25.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/34e06e73701d42b8a9da910897df45e0.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/304f07507ebc413ea5167781955df8fb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9979225fed0646048032d0a289e01989.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.69022626},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.2777597},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.8417509},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.80098265}]', NULL, NULL, NULL, NULL, '2026-05-20 14:27:09', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (334, 141, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 10:41:19', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (335, 141, 'assistant', '该提示框是系统执行某项操作（如删除、清理等）后的标准反馈，通常为**自动关闭型提示**，无需用户手动点击确认。  \n若提示框未自动关闭或反复弹出，可尝试以下操作：  \n1. **等待约5–10秒**，观察是否自动消失；  \n2. 若长时间未关闭，按键盘 **Esc 键**强制关闭；  \n3. 检查当前操作是否触发了重复执行逻辑（如误双击按钮）；  \n4. 刷新页面或重启相关软件（如UG、蓝U）后重试。  \n\n如问题持续出现，可能涉及程序异常或权限冲突，建议记录具体操作步骤及截图，以便进一步排查。  \n（参考:通用交互提示-系统反馈机制）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645}]', NULL, NULL, NULL, NULL, '2026-05-21 10:41:31', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (336, 142, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 10:41:32', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (337, 142, 'assistant', '您描述的是执行某项操作（如「删除属性」）后弹出的提示框，该提示框说明操作已执行、即将自动关闭。根据知识库中「赋属性工具」的操作注意事项：\n\n1. **点击“删除属性”按钮后**，系统会弹出确认提示框（如“已执行删除操作，此对话框即将关闭”）；  \n2. **必须在弹出框中点击“确定”**，才能使删除操作真正生效；  \n3. 若仅等待提示框自动关闭或点击“取消”/关闭×，则**删除不会生效**。\n\n⚠️ 注意：该提示框是操作反馈，不是确认提交——关键动作仍是手动点击**确定**。（参考:赋属性工具-caution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6003254}]', NULL, NULL, NULL, NULL, '2026-05-21 10:41:38', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (338, 143, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 10:41:38', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (339, 143, 'assistant', '您描述的是执行「删除属性」操作后弹出的提示框，该提示框仅表示操作已触发，**但尚未真正生效**。\n\n请按以下步骤确保删除操作完成：\n\n1. **点击“删除属性”按钮**（位于赋属性工具界面）；  \n2. 弹出确认提示框（含“已执行某项操作……即将关闭”字样）；  \n3. **必须在该提示框关闭前，主动点击“确定”按钮**——这是关键步骤，否则删除不会生效；  \n4. 确认后，系统将正式删除所选属性，并刷新界面显示。\n\n⚠️ 注意：仅点击“删除属性”而未点“确定”，属于常见误操作，会导致属性实际未被删除。（参考:赋属性工具-caution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6003254}]', NULL, NULL, NULL, NULL, '2026-05-21 10:41:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (340, 144, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:39:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (341, 144, 'assistant', '您描述的是执行某项操作（如「删除属性」）后弹出的提示框，该提示框说明操作已执行、即将自动关闭。根据知识库信息：\n\n1. **确认生效是关键步骤**：在「赋属性工具」中执行「删除属性」后，**必须点击“确定”按钮**，否则删除操作不会真正生效；仅点击“删除属性”按钮后不点“确定”，属于常见误操作。  \n2. 若提示框为自动关闭型（无手动确认按钮），请留意是否已完成最终提交——部分界面需在提示前额外点击“应用”或“保存”。  \n3. 建议操作后检查目标对象属性是否实际被移除，以验证操作是否成功。\n\n如您遇到该提示后属性未被删除，或提示框异常无法关闭，请提供具体操作场景（如在哪个功能模块、点击了什么按钮），我可进一步协助判断。(参考:赋属性工具-caution)', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6003254}]', NULL, NULL, NULL, NULL, '2026-05-21 11:39:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (342, 145, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:39:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (343, 145, 'assistant', '您描述的是执行某项操作（如「删除属性」）后弹出的提示框，该提示框说明操作已执行、即将自动关闭。根据知识库中「赋属性工具」的操作注意事项：\n\n1. **确认操作是否真正生效**：仅点击“删除属性”按钮后，系统会弹出提示框，但**必须点击“确定”** 才能使删除操作最终生效；  \n2. 若未点击“确定”，仅等待提示框自动关闭，则删除操作**并未实际执行**；  \n3. 建议在提示框弹出后，主动点击其中的**“确定”按钮**，确保操作完成。\n\n（参考: 赋属性工具-caution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.6003254}]', NULL, NULL, NULL, NULL, '2026-05-21 11:40:05', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (344, 146, 'user', '弹出提示框：已执行某项操作,该操作可删除......此对话框即将关闭。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:40:05', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (345, 146, 'assistant', '您描述的是一个系统提示对话框，内容为“已执行某项操作，该操作可删除……此对话框即将关闭”。该提示通常属于**系统自动关闭型确认/提示弹窗**，常见于执行删除、提交或同步类操作后的反馈。\n\n但根据当前知识库信息：\n- 无关于该提示框的具体触发场景、所属功能模块或关闭逻辑的说明；\n- 无对应的操作指引（如：如何避免弹出、如何延长显示时间、是否支持手动关闭等）；\n- 也未在FAQ中匹配到相似问题。\n\n关于这个问题，我目前的知识库暂未覆盖完整答案。需要我帮您提交工单，让技术人员进一步协助吗？', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/93db62dde0eb45019642906c4fb371fd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43592453},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.42118645}]', NULL, NULL, NULL, NULL, '2026-05-21 11:40:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (346, 147, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:40:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (347, 147, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**  \n   - 错误原因：导出时“分页行数”设为＞20（如40），超出系统单页最大允许行数（默认20），导致分页逻辑异常、数据错位或截断。  \n   - 解决：重新导出，将**分页行数严格设为≤20**（推荐20或更低，如15）。\n\n2. **未先扫描BOM表就导出**  \n   - 错误原因：“扫描所有实体出BOM表”是导出前提，未扫描则内存无数据源，导出结果不可控。  \n   - 解决：执行**步骤四“扫描所有实体出BOM表”后再导出**。\n\n✅ 预防措施：导出前务必检查分页行数是否≤20，并确保已完成扫描动作。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3348278},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.90973794},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-21 11:40:18', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (348, 148, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:40:18', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (349, 148, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**  \n   - 错误原因：导出时“分页行数”设为＞20（如40），超出系统单页最大允许行数（默认20），导致分页逻辑异常、数据错位或截断。  \n   - 解决：重新导出，将**分页行数严格设为≤20**（推荐20或更低，如15）。\n\n2. **未先扫描BOM表就导出**  \n   - 错误原因：“扫描所有实体出BOM表”是导出前提，未扫描则内存无数据源，导出结果不可控。  \n   - 解决：执行**步骤四“扫描所有实体出BOM表”后再导出**。\n\n✅ 预防措施：导出前务必检查分页行数输入框，默认值或惯性填入“40”会直接触发乱码。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3348278},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.90973794},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-21 11:40:25', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (350, 149, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:40:25', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (351, 149, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**：导出时“分页行数”超过系统允许上限（**必须 ≤20**），导致分页逻辑异常，后续转TXT或显示时行序错乱。  \n   ✅ 解决：重新扫描BOM → 进入导出设置 → 将“分页行数”**手动改为20或更低（如15）** → 再导出。\n\n2. **未先扫描即导出**：BOM数据未通过“扫描所有实体”生成，导出基于空/不完整数据源，引发行数异常。  \n   ✅ 解决：确保执行**步骤四“扫描所有实体出BOM表”完成后再导出**。\n\n3. **总行数与分页不匹配**：如BOM共35行却设分页为20，第2页仅15行，部分工具解析时易截断或错位。  \n   ✅ 预防：优先选用≤20的保守值，避免依赖自动计算。\n\n⚠️ 注意：导出Excel是转TXT的前提，且**分页功能必须勾选后才生效**，默认值“40”是常见诱因。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3348278},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.90973794},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-21 11:40:33', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (352, 150, 'user', '为甚使用BOM导出TXT文本失败？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:40:34', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (353, 150, 'assistant', '您遇到的是 **BOM导出TXT文本失败** 的问题。可能原因及解决步骤如下：\n\n1. **按钮灰显/不可用**  \n   → 原因：未先执行“导出EXCEL表”操作（TXT转换功能强依赖EXCEL已生成）。  \n   → 解决：务必先完成**步骤五：点击导出EXCEL**，待保存提示弹出后再点“EXCEL转TXT文本”。\n\n2. **导出后乱码或转换失败**  \n   → 原因：EXCEL导出时设置的**分页行数 > 20**，超出系统分页逻辑容限，导致TXT解析错位。  \n   → 解决：重新导出EXCEL，将“分页行数”设为**≤20**（推荐固定为20）。\n\n**预防建议**：在操作指南中将“导出EXCEL”明确为TXT转换的强制前置步骤，并默认锁定分页行数为20。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.6282047},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.4548791},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8719525},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8615391},{\"featureName\":\"BOM工具\",\"chunkType\":\"prerequisite\",\"score\":0.7545464},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.719066}]', NULL, NULL, NULL, NULL, '2026-05-21 11:40:40', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (354, 151, 'user', '为甚使用BOM导出TXT文本失败？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:40:41', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (355, 151, 'assistant', '您遇到的是 **BOM导出TXT文本失败** 的问题。可能原因及解决步骤如下：\n\n1. **按钮灰显/不可用**  \n   - 原因：未先执行“导出EXCEL表”操作，TXT转换功能有强前置依赖。  \n   - 解决：务必先完成【步骤五：点击导出EXCEL】，待EXCEL文件成功生成并弹出保存提示后，再点击“EXCEL转TXT文本”。\n\n2. **导出后出现乱码或失败**  \n   - 原因：导出EXCEL时设置的“分页行数”超过系统安全阈值（如设为40，但应≤20）。  \n   - 解决：重新导出EXCEL，将分页行数严格设为 **≤20**（推荐固定为20），再尝试转TXT。\n\n**预防措施**：操作前确认已导出EXCEL；分页行数输入框默认值勿沿用40，须手动检查并修正为≤20。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.6282047},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.4548791},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8719525},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8615391},{\"featureName\":\"BOM工具\",\"chunkType\":\"prerequisite\",\"score\":0.7545464},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.719066}]', NULL, NULL, NULL, NULL, '2026-05-21 11:40:47', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (356, 152, 'user', '为甚使用BOM导出TXT文本失败？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:40:48', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (357, 152, 'assistant', '您遇到的是 **BOM导出TXT文本失败** 的问题。可能原因及解决步骤如下：\n\n1. **按钮灰显/不可点击**  \n   → 原因：未先执行“导出EXCEL表”操作（TXT转换功能强依赖EXCEL已生成）。  \n   → 解决：务必先完成**步骤五：点击导出EXCEL**，待弹出保存提示后再点“EXCEL转TXT文本”。\n\n2. **点击后无响应或报错**  \n   → 原因：分页行数设置超过系统允许上限（如设为40），导致格式异常、解析失败。  \n   → 解决：重新导出EXCEL，将**分页行数严格设为 ≤20**（推荐20，避免越界乱码）。\n\n✅ 预防：操作中始终将“导出EXCEL”作为TXT转换的强制前置步骤，并在勾选“分页”时主动检查并修正行数值。（参考:BOM工具-error_solution）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.6282047},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.4548791},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8719525},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.8615391},{\"featureName\":\"BOM工具\",\"chunkType\":\"prerequisite\",\"score\":0.7545464},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.719066}]', NULL, NULL, NULL, NULL, '2026-05-21 11:40:54', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (358, 153, 'user', '我在使用快速涂色功能的时候,为什么上色功能失败？弹出个提示框,说是找不到配置表。', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:40:55', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (359, 153, 'assistant', '您在使用「快速涂色」时遇到“找不到配置表”的提示，**根本原因是未预先设置建模档出图标准**（如“启泰”标准），导致系统无法加载特征注解表和材质颜色表。\n\n可能原因与解决步骤如下：\n\n1. **未设置设计标准**  \n　→ 进入【建模档出图标准设置】，手动选择对应品牌标准（如“启泰”）；\n\n2. **虽设标准但配置表未正确关联**  \n　→ 分别打开【特征注解表】和【材质颜色表】，确认能正常加载并完成参数配置；\n\n3. **配置表路径异常或损坏**（较少见）  \n　→ 重启UG及蓝U，重试设置流程；若仍失败，可提交工单由技术人员检查配置文件完整性。\n\n**预防建议**：每次启动「快速涂色」前，务必先完成出图标准设置，并将常用标准固化为项目默认项。(参考: 快速涂色-error_solution)', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.8587271},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.55851966},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.87974805},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8012762},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.75509983}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:01', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (360, 154, 'user', '我在使用快速涂色功能的时候,为什么上色功能失败？弹出个提示框,说是找不到配置表。', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:01', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (361, 154, 'assistant', '您在使用「快速涂色」时遇到**上色失败并提示“找不到配置表”**，这是典型的标准缺失问题。\n\n可能原因及解决步骤如下：\n\n1. **未设置出图标准**（最常见）  \n　→ 进入【建模档出图标准设置】，**手动选择对应品牌的设计标准**（如“启泰”）；\n\n2. **配置表未加载或路径异常**  \n　→ 确认已通过【特征注解表】和【材质颜色表】完成参数配置；  \n　→ 单击“打开配置表”，检查是否能正常弹出并读取内容。\n\n**预防措施**：每次启动「快速涂色」前，务必先完成出图标准设置；建议在项目初始化阶段将标准固化为默认项。\n\n(参考: 快速涂色-error_solution)', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.8587271},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.55851966},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.87974805},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8012762},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.75509983}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:07', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (362, 155, 'user', '我在使用快速涂色功能的时候,为什么上色功能失败？弹出个提示框,说是找不到配置表。', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:07', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (363, 155, 'assistant', '您遇到的是「快速涂色」功能报错：“找不到配置表”。\n\n可能原因及解决步骤如下：\n\n1. **未设置出图标准**（最常见）  \n　→ 进入【建模档出图标准设置】，手动选择对应品牌的设计标准（如“启泰”）。\n\n2. **配置表未正确加载**  \n　→ 确认已通过【特征注解表】和【材质颜色表】完成参数配置；点击“打开配置表”检查路径是否有效。\n\n3. **功能前置条件不满足**  \n　→ 若未设标准，体/孔/键槽将显示为红色字体，“一键涂色”按钮不可用或无效。\n\n✅ 预防建议：每次使用前先完成标准设置，并在项目初始化阶段固化为默认项。\n\n（参考: 快速涂色-error_solution）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.8587271},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.55851966},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.87974805},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8012762},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.75509983}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:13', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (364, 156, 'user', '使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要怎么改？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:13', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (365, 156, 'assistant', '根据知识库，该提示出现是因为勾选「重量」功能后设置了重量预值，且当前备料板估算重量超过该预值。以下是修改方法：\n\n1. **修改重量预值**：在「预设值」区域，将「重量」预设值调大（或设为0表示不限）；  \n2. **优化备料内容**：减少备料板内工件数量，或更换密度更低的材质工件；  \n3. **预估校验**：设置前，先通过「外形尺寸」×材料密度粗略估算总重，确保预值合理。\n\n（参考: 建模档合并订料-error_solution）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/0b3e241de6c84fea99d8a880fe21bb89.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d998d701cc314fa396a996180e38e31e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6c796acc3d604f92a84eccaa72960524.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.94574517},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37372708},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"error_solution\",\"score\":0.9105971},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"operation_guide\",\"score\":0.903606},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.78844434}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:18', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (366, 157, 'user', '使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要怎么改？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:18', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (367, 157, 'assistant', '根据知识库，该提示出现是因为勾选「重量」功能后设置了重量预值，且当前备料板估算重量超过该预值。修改方法如下：\n\n1. **打开「预设值」设置**：在建模档合并订料界面，找到并点击「预设值」按钮；  \n2. **调整重量预值**：在弹出的设置中，将「重量」预值修改为更大数值，或设为 **0（表示不限重）**；  \n3. **同步优化备料内容**（可选）：若需保留重量限制，可减少备料板内工件数量，或更换密度更低的材质工件；  \n4. **验证估算合理性**：建议先用「外形尺寸」结合材料密度粗估总重，再设定合理预值。\n\n（参考: 建模档合并订料-error_solution）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/0b3e241de6c84fea99d8a880fe21bb89.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d998d701cc314fa396a996180e38e31e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6c796acc3d604f92a84eccaa72960524.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.94574517},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37372708},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"error_solution\",\"score\":0.9105971},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"operation_guide\",\"score\":0.903606},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.78844434}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (368, 158, 'user', '使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要怎么改？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (369, 158, 'assistant', '根据知识库，该提示出现是因为勾选「重量」功能后设置了重量预值，且当前备料板估算重量超过该预值。修改方法如下：\n\n1. **修改重量预值**：在「预设值」步骤中，将「重量」预值调大，或设为 **0 表示不限重**；  \n2. **优化备料内容**：减少单块备料板内的工件数量，或更换密度更小的材质工件；  \n3. **前置估算**：设置预值前，先通过「外形尺寸」×材料密度粗略估算总重，避免盲目设限。\n\n（参考: 建模档合并订料-error_solution）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/0b3e241de6c84fea99d8a880fe21bb89.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d998d701cc314fa396a996180e38e31e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6c796acc3d604f92a84eccaa72960524.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.94574517},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37372708},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"error_solution\",\"score\":0.9105971},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"operation_guide\",\"score\":0.903606},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.78844434}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:31', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (370, 159, 'user', '赋属性工具中编辑原点的功能有什么作用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:31', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (371, 159, 'assistant', '**编辑原点**功能用于检查和修改单个或批量工件的原点位置，是确保后续建模、出图及属性赋值准确性的关键前置操作。\n\n典型应用场景包括：\n1. **原点校验**：勾选“检查原点”后显示所有坯料框，快速识别原点偏移或缺失的工件；\n2. **批量调整**：对多个工件统一设置原点（如四面分中或左下角），提升标准化效率；\n3. **适配规则**：结合“规则2”按长宽比（如10:1）自动判断工件形态并优化原点策略。\n\n该功能是「赋属性工具」的核心子功能，必须在执行属性写入前完成，且严格依赖“勾选检查原点→选择工件→应用更新→确定”的操作链。（参考: 赋属性工具 - feature_detail）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.27905914},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.25713286},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_detail\",\"score\":0.835248},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7581718}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (372, 160, 'user', '赋属性工具中编辑原点的功能有什么作用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:38', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (373, 160, 'assistant', '**编辑原点功能**用于检查并修改单个或批量工件的坐标原点位置，是确保后续出图、加工及属性赋值准确性的关键前置操作。\n\n典型应用场景包括：  \n1. **批量校准坯料定位**：勾选“检查原点”后显示所有坯料框，统一调整多个工件原点至设计要求位置；  \n2. **适配不同建模习惯**：支持将原点设为四面分中或左下角，满足长条形（如长宽比10:1）等特殊工件的定位规则；  \n3. **保障属性写入准确性**：原点位置直接影响零件编号、长宽高、重量等属性的计算与标注，是「赋属性工具」生成建模档实体属性的前提。\n\n该功能属于「赋属性工具」的核心子功能，必须在完成「检查原点→选择工件→应用更新→确定」完整操作链后才生效。（参考: 赋属性工具 - feature_detail）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.27905914},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.25713286},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_detail\",\"score\":0.835248},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7581718}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (374, 161, 'user', '赋属性工具中编辑原点的功能有什么作用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:45', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (375, 161, 'assistant', '**编辑原点功能**用于检查并修改单个或批量工件的坐标原点位置，是确保后续出图、加工及属性赋值准确性的关键前置操作。\n\n典型应用场景包括：  \n1. **批量校准坯料定位**：勾选“检查原点”后显示所有坯料框，统一调整多个工件原点至设计要求位置；  \n2. **适配不同建模习惯**：支持将原点设为四面分中或左下角，满足长条形（如长宽比10:1）等特殊工件的定位规则；  \n3. **保障属性写入准确性**：原点位置直接影响零件编号、长宽高、重量等属性的计算与标注，是「赋属性工具」生成建模档实体属性的前提。\n\n该功能属于「赋属性工具」的核心子功能，必须在完成「检查原点→选择工件→应用更新→确定」完整操作链后才生效。（参考: 赋属性工具 - feature_detail）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.27905914},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.25713286},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_detail\",\"score\":0.835248},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8263519},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7581718}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:52', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (376, 162, 'user', '出图的前置条件是什么？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:52', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (377, 162, 'assistant', '「出图预设」是智一系统中用于设置出图标准与公共信息（如客户、模号）的功能，支持公共信息自动关联出图及导BOM。\n\n其核心前置条件为：  \n1. **必须先执行「出图预设」中的“选择用户标准”**；  \n2. 该操作是后续填写公共信息、执行快速涂色等动作的前提；  \n3. 若未选择标准，系统将弹出错误提示，且无法继续相关操作（如快速涂色）。\n\n该功能与「快速涂色」「BOM导出」等功能存在强依赖关系，是出图流程的起始配置环节。(参考: 出图预设 - prerequisite)', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/02d6015ef25d4cf78c35eaf49a44fd91.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37094852},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3303719},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.78948605},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.75693196},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.671205}]', NULL, NULL, NULL, NULL, '2026-05-21 11:41:57', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (378, 163, 'user', '出图的前置条件是什么？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:41:58', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (379, 163, 'assistant', '「出图预设」是智一系统中用于统一设置出图标准与公共信息（如客户、模号等）的功能，支撑公共信息自动关联出图及BOM导出。\n\n其核心前置条件为：  \n1. **必须先完成“选择用户标准”**——这是执行快速涂色等后续操作的前提；  \n2. **标准选定后，才能动态加载对应的基本属性配置表**，进而填写该标准下允许的公共信息字段；  \n3. 若跳过此步，系统将弹出错误提示，且无法继续执行快速涂色等依赖操作。\n\n该功能是「快速涂色」「BOM导出」等出图相关操作的基础依赖。(参考: 出图预设 - prerequisite)', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/02d6015ef25d4cf78c35eaf49a44fd91.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37094852},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3303719},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.78948605},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.75693196},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.671205}]', NULL, NULL, NULL, NULL, '2026-05-21 11:42:03', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (380, 164, 'user', '出图的前置条件是什么？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:42:03', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (381, 164, 'assistant', '「出图预设」是智一系统中用于统一设置出图标准与公共信息（如客户、模号等）的功能，支撑公共信息自动关联出图及BOM导出。\n\n其核心前置条件为：  \n1. **必须先完成“选择用户标准”**——这是执行快速涂色等后续操作的前提；  \n2. **标准选定后，才能动态加载对应的基本属性配置表**，进而填写该标准下允许的公共信息字段；  \n3. 若跳过此步，系统将弹出错误提示，且无法继续执行快速涂色等依赖操作。\n\n该功能是「快速涂色」「BOM导出」等出图相关操作的基础依赖。(参考: 出图预设 - prerequisite)', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/02d6015ef25d4cf78c35eaf49a44fd91.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.37094852},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3303719},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.78948605},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.75693196},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.671205}]', NULL, NULL, NULL, NULL, '2026-05-21 11:42:08', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (382, 165, 'user', '为什么导出的图没有注解？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:42:08', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (383, 165, 'assistant', '您遇到的问题是：**导出的图纸中缺少注解内容**。\n\n可能原因及解决步骤如下：\n\n1. **未设置出图预设中的用户标准**  \n   → 进入「出图预设」功能 → 执行**步骤一：选择用户标准**（如“启泰”标准），确保标准已生效。\n\n2. **所选标准下未配置注解相关公共信息字段**  \n   → 核实该用户标准对应的基本属性配置表，确认“注解”或相关字段（如“技术要求”“说明”）已被启用为公共信息；如有缺失，需联系管理员补充配置。\n\n3. **导出操作未勾选注解输出选项**（若界面存在相关设置）  \n   → 检查导出对话框中是否有“包含注解”“输出公共信息”等复选框，确保已勾选。\n\n**预防建议**：每次新建项目或切换标准后，先完成「出图预设」全流程配置，再执行导图、涂色、导BOM等依赖操作。(参考: 出图预设 - error_solution)', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/135f645e3ef54410b6167b39d47db15b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/b910649ba6e147578475c7ae5468d788.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d185b8cecec3455997ea3739bc436f4f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6b6bba4a459883c88177a901022f.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/02d6015ef25d4cf78c35eaf49a44fd91.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43698773},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.40168068},{\"featureName\":\"出图预设\",\"chunkType\":\"error_solution\",\"score\":0.653272},{\"featureName\":\"出图预设\",\"chunkType\":\"caution\",\"score\":0.5578602},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.55678236}]', NULL, NULL, NULL, NULL, '2026-05-21 11:42:15', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (384, 166, 'user', '为什么导出的图没有注解？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:42:15', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (385, 166, 'assistant', '您遇到的问题是：**导出的图纸中缺少注解（如英文注解、槽注解等）**。\n\n可能原因及解决步骤如下：\n\n1. **未在配置表中正确设置注解选项**  \n   - 建模出图工具的注解参数（如“英文注解”“槽注解”）需提前在**基本属性工作表**中勾选并保存，**不能在出图界面临时设置**。  \n   - ✅ 解决：打开配置表 → 进入“基本属性”工作表 → 勾选所需注解项 → 保存 → 再执行出图。\n\n2. **跳过配置表直接出图，使用了旧值或默认值**  \n   - 若未打开并修改配置表，系统将沿用上次值或默认不启用注解。  \n   - ✅ 解决：严格按顺序操作：**打开配置表 → 修改基本属性 → 执行出图**。\n\n3. **勾选冲突或隐含约束（如启用“英制牙”影响单位制）**  \n   - 某些选项间存在联动约束，可能导致注解未生效。  \n   - ✅ 解决：对照《模具出图规范》逐项核对客户特殊要求。\n\n📌 **后续注意事项**：所有工艺标记类选项均属关键合规项，务必出图前完成配置表确认。（参考: 建模出图工具-caution & dependency）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43698773},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.40168068},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087}]', NULL, NULL, NULL, NULL, '2026-05-21 11:42:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (386, 167, 'user', '为什么导出的图没有注解？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:42:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (387, 167, 'assistant', '您遇到的问题是：**导出的图纸中缺少注解（如英文注解、槽注解等）**。\n\n可能原因及解决步骤如下：\n\n1. **未在配置表中正确设置注解选项**  \n   - 建模出图工具的注解参数（如“英文注解”“槽注解”）需提前在**基本属性工作表**中勾选并保存，**不能在出图界面临时设置**。  \n   - ✅ 解决：打开配置表 → 进入“基本属性”工作表 → 勾选所需注解项 → 保存 → 再执行出图。\n\n2. **跳过配置表直接出图，使用了旧值或默认值**  \n   - 若未打开并修改配置表，系统将沿用上次值或默认不启用注解。  \n   - ✅ 解决：严格按顺序操作：**打开配置表 → 修改基本属性 → 执行出图**。\n\n3. **勾选冲突或隐含约束（如启用“英制牙”影响单位制）**  \n   - 某些选项间存在联动约束，可能导致注解未生效。  \n   - ✅ 解决：对照《模具出图规范》逐项核对客户特殊要求。\n\n📌 **后续注意事项**：所有工艺标记类选项均属关键合规项，务必出图前人工复核。（参考: 建模出图工具-caution & dependency）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43698773},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.40168068},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.5896204},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.58412087}]', NULL, NULL, NULL, NULL, '2026-05-21 11:42:33', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (388, 168, 'user', '备料板尺寸的大小是否会随前距、后距、左距、右距的值变化而产生变化？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:42:33', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (389, 168, 'assistant', '是的，**备料板尺寸的大小会随前距、后距、左距、右距的值变化而变化**。  \n这些间距参数**共同决定备料板的最终尺寸**，若仅调整其中某一项而忽略其他，可能导致外形尺寸估算失真，进而影响「外形尺寸」超限判断或「备料数量」误判。  \n建议在调整时**同步审视所有间距参数**，并结合「外形尺寸」实时估算结果协同优化。（参考:建模档合并订料-caution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c227c756052c42a09bcbc34f9fd67e02.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/78aa466378be4cb498660f1a76541905.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/3fca5c3984c1462a8f7a288f4db67089.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f53dbd52e7cd4d2b8ecc90b9e88c732d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ff6dca94663145e8b4ac870c07011a30.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4733348413e4496dad66233b69210d6c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.27148286},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.26537177},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7716138},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.71892637}]', NULL, NULL, NULL, NULL, '2026-05-21 11:42:39', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (390, 169, 'user', '备料板尺寸的大小是否会随前距、后距、左距、右距的值变化而产生变化？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:42:39', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (391, 169, 'assistant', '是的，**备料板尺寸的大小会随前距、后距、左距、右距的值变化而变化**。  \n这些参数共同决定备料板的最终尺寸，若仅调整其中某一项而忽略其他，可能导致外形尺寸估算失真，进而影响「外形尺寸」超限判断或「备料数量」误判。\n\n建议：同步审视所有间距参数（前距/后距/左距/右距/行距/列距/上距/下距），并结合「外形尺寸」实时估算结果协同调整。（参考:建模档合并订料-caution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c227c756052c42a09bcbc34f9fd67e02.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/78aa466378be4cb498660f1a76541905.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/3fca5c3984c1462a8f7a288f4db67089.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f53dbd52e7cd4d2b8ecc90b9e88c732d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ff6dca94663145e8b4ac870c07011a30.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4733348413e4496dad66233b69210d6c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.27148286},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.26537177},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7716138},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.71892637}]', NULL, NULL, NULL, NULL, '2026-05-21 11:42:45', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (392, 170, 'user', '备料板尺寸的大小是否会随前距、后距、左距、右距的值变化而产生变化？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:42:46', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (393, 170, 'assistant', '是的，**备料板尺寸的大小会随前距、后距、左距、右距的值变化而变化**。\n\n这是「建模档合并订料」功能中的关键机制，具体表现为：\n1. **动态影响备料板长宽高**：四个距离参数共同参与备料板最终尺寸计算；\n2. **关联外形尺寸超限判断**：若参数设置不当，可能导致系统误判工件是否超出加工行程；\n3. **影响备料数量估算**：单个参数调整未协同其他参数时，易造成备料数量误判。\n\n该功能属于「建模档合并订料」核心操作环节，与「行距/列距/上距/下距」等间距参数协同作用，共同决定备料板布局与尺寸。（参考: 建模档合并订料 - feature_detail）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/c227c756052c42a09bcbc34f9fd67e02.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/78aa466378be4cb498660f1a76541905.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/3fca5c3984c1462a8f7a288f4db67089.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f53dbd52e7cd4d2b8ecc90b9e88c732d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/ff6dca94663145e8b4ac870c07011a30.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4733348413e4496dad66233b69210d6c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.27148286},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.26537177},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7716138},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.71892637}]', NULL, NULL, NULL, NULL, '2026-05-21 11:42:53', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (394, 171, 'user', '如何使用赋属性这个功能？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:42:53', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (395, 171, 'assistant', '以下是「赋属性工具」的操作步骤：\n\n1. **选择写入属性及客户标准**  \n   在工具界面顶部选择需写入的属性（如零件编号、长宽高、材质等）和对应**客户标准**，注意确认用户标准是否匹配。\n\n2. **选择零件**  \n   可**框选工件**，或点击「扫描」自动识别并排序已建模工件；也可按配置表「全选工件」。\n\n3. **设置零件编码排序与主视图方向**  \n   检查客户标准要求；选择上模/下模的**俯视图或仰视图**作为主视图。\n\n4. **设置原点方向规则**  \n   - 默认以长直边、短直边为零边（长度≥400视为大板）；  \n   - 勾选「规则1」可指定某颜色边为零边（3D模型需提前涂色）；  \n   - 勾选「规则2」可自定义长宽比（如10:1）及原点位置（四面分中或左下角）。\n\n5. **执行编辑或添加余量（如需）**  \n   - 先勾选「检查原点」→ 显示坯料框 → 选择工件 → 修改原点位置；  \n   - 或勾选「检查余量」→ 选择工件 → 自定义余量值；  \n   - **每步修改后必须依次点击「应用更新」→「确定」**，否则不生效。（参考:赋属性工具-operation_guide）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3584834},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35214302},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8652982},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7550333}]', NULL, NULL, NULL, NULL, '2026-05-21 11:43:02', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (396, 172, 'user', '如何使用赋属性这个功能？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:43:02', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (397, 172, 'assistant', '以下是「赋属性工具」的操作步骤：\n\n1. **选择写入属性及客户标准**  \n　　在工具界面顶部选择需写入的属性（如零件编号、长宽高、材质等）和对应**客户标准**，注意确认用户标准是否匹配。\n\n2. **选择零件**  \n　　支持**框选工件**或点击「按配置表全选工件」；若勾选「扫描」，则自动识别并排序已加载工件。\n\n3. **设置零件编码排序与主视图方向**  \n　　检查客户标准中排序逻辑；选择上/下模的**俯视图或仰视图**作为主视图。\n\n4. **设置原点方向规则**  \n　　- 默认以长直边+短直边为零边，长度≥400mm视为大板；  \n　　- 勾选「规则1」可指定某颜色边为零边（3D模型需提前涂色）；  \n　　- 勾选「规则2」可自定义长宽比（如10:1），并设置原点为四面分中或左下角。\n\n5. **执行关键操作时务必完成两步**  \n　　如「编辑原点」或「添加余量」：先点**应用更新** → 再点**确定**，否则修改不生效。（参考:赋属性工具-operation_guide）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3584834},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35214302},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8652982},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7550333}]', NULL, NULL, NULL, NULL, '2026-05-21 11:43:10', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (398, 173, 'user', '如何使用赋属性这个功能？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:43:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (399, 173, 'assistant', '以下是「赋属性工具」的操作步骤：\n\n1. **选择写入属性及客户标准**  \n   在工具界面顶部选择需写入的属性（如零件编号、长宽高、材质等）和对应**客户标准**，注意正确选择用户标准。\n\n2. **选择零件**  \n   可**框选工件**，或点击「扫描」自动识别并排序已加载工件。\n\n3. **设置零件编码排序**  \n   检查客户标准要求，确认编号逻辑（如按位置、尺寸或配置表顺序）。\n\n4. **设定主视图方向**  \n   根据模具类型选择：上模/下模的**俯视图或仰视图**。\n\n5. **配置原点方向规则**  \n   - 默认以长直边+短直边为零边；长度＞400视为大板（可自定义分界值）；  \n   - 勾选「规则1」：指定某颜色为零边（3D模型需提前涂色）；  \n   - 勾选「规则2」：自定义长宽比（如10:1），并选择原点位置（四面分中或左下角）。\n\n6. **执行编辑/添加操作（如需）**  \n   - 编辑原点或添加余量时，务必先点**应用更新**，再点**确定**，否则不生效。（参考:赋属性工具-operation_guide）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3584834},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35214302},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8652982},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"caution\",\"score\":0.75967574},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.7550333}]', NULL, NULL, NULL, NULL, '2026-05-21 11:43:19', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (400, 174, 'user', '如何使用BOM表工具这个功能？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:43:19', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (401, 174, 'assistant', '以下是使用BOM表工具的详细操作步骤：\n\n1. **前置条件**：确保已打开含BOM数据的图档，并完成客户信息、模号、产品编号的填写与核对。  \n2. 选择BOM表类型（如材料清单、标准件清单、成本预算单）。  \n3. 按需勾选「已备料不出料单」，设置是否分页、分页类型及**分页行数（不可超过原表格最大行数，如20，否则导致乱码）**。  \n4. **扫描整个图档或手动选择实体**，生成BOM数据源（此为导出前提，未扫描则导出为空或报错）。  \n5. 点击「导出EXCEL」；导出后如需，可进一步点击「EXCEL转TXT文本」。  \n\n所有清单（材料/标准件/成本预算）操作流程一致。(参考: BOM工具-operation_guide)', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.56506085},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3302302},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32617375},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8322726},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.717364}]', NULL, NULL, NULL, NULL, '2026-05-21 11:43:26', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (402, 175, 'user', '如何使用BOM表工具这个功能？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:43:26', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (403, 175, 'assistant', '以下是使用BOM表工具的操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：如“已备料不出料单”“是否分页”，并设置**分页类型和行数**（注意：分页行数不可超过原表格最大行数，如20，否则会导致乱码）  \n4. **扫描BOM表**：可扫描整个图档，或手动**选择实体生成**BOM数据（此为导出前提，无扫描则导出为空或报错）  \n5. **点击“导出EXCEL”**；导出后如需，可进一步点击**EXCEL转TXT文本**\n\n（参考:BOM工具-operation_guide）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.56506085},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3302302},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32617375},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8322726},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.717364}]', NULL, NULL, NULL, NULL, '2026-05-21 11:43:32', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (404, 176, 'user', '如何使用BOM表工具这个功能？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:43:32', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (405, 176, 'assistant', '以下是使用BOM表工具的操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**（前置条件：确保信息准确）  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：如“已备料不出料单”“是否分页”，并设置分页类型和行数（注意：分页行数不能超过原表格最大行数，如20，否则会乱码）  \n4. **生成BOM数据源**：扫描整个图档或**选择实体生成**（此步为导出前提，未扫描则导出为空或报错）  \n5. **点击“导出EXCEL”**；导出后如需，可进一步点击“EXCEL转TXT文本”  \n\n所有清单（材料/标准件/成本预算）操作方式一致。（参考: BOM工具-operation_guide）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.56506085},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.3302302},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32617375},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8322726},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.717364}]', NULL, NULL, NULL, NULL, '2026-05-21 11:43:38', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (406, 177, 'user', '如何使用建模出图工具这个功能？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:43:38', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (407, 177, 'assistant', '以下是使用「建模出图工具」的操作步骤：\n\n1. **前置条件**：先**打开配置表**（含基本属性工作表），在其中修改模具编号、球标大小、加工说明等参数（文档强调“打开基本属性表可修改”）；  \n2. 填写**模具编号**（依赖配置表已打开）；  \n3. 选择要出图的零件类型：**常规出图零件** 或 **轻量化出图零件**；  \n4. 选择投影视角：**第一视角** 或 **第三视角**（决定后续视图方向）；  \n5. 勾选所需视图及符号：主/右/前视图、**球标图**、**线割涂色**、**研磨符号**；  \n6. 设置**球标大小**，按需勾选**加工说明**、**英文注解**、**英制牙**，选择**做深/掏留**、**槽注解**；  \n7. **填写图纸路径**（必须在所有参数设定完毕后指定）；  \n8. 点击**确定**执行出图，完成后前往指定路径查看图纸。  \n(参考: 建模出图工具-operation_guide)', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/cae11a9be14d4c6d8093040d8705b7c1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35652167},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.31158954},{\"featureName\":\"建模出图工具\",\"chunkType\":\"operation_guide\",\"score\":0.9246347},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78007317}]', NULL, NULL, NULL, NULL, '2026-05-21 11:43:46', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (408, 178, 'user', '如何使用建模出图工具这个功能？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:43:46', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (409, 178, 'assistant', '以下是使用「建模出图工具」的操作步骤：\n\n1. **前置条件**：先**打开配置表**（含基本属性工作表），在其中修改模具编号、球标大小、加工说明等参数（文档强调“打开基本属性表可修改”）  \n2. 填写**模具编号**（依赖配置表已打开）  \n3. 选择要出图的零件类型：**常规出图零件** 或 **轻量化出图零件**  \n4. 选择投影视角：**第一视角** 或 **第三视角**（决定后续视图方向）  \n5. 设置视图及符号：勾选**主视图/右视图/前视图**，按需勾选**球标图、线割涂色（默认红色186）、研磨符号**  \n6. 配置球标与注解：设置**球标大小**，勾选**加工说明、英文注解、英制牙**，选择**做深/掏留**，填写**槽注解**  \n7. 指定**图纸路径**（最后输出环节的必要输入）  \n8. 点击**确定**，待出图完毕后，前往图纸路径查看生成的2D图纸  \n\n(参考: 建模出图工具-operation_guide)', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/cae11a9be14d4c6d8093040d8705b7c1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35652167},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.31158954},{\"featureName\":\"建模出图工具\",\"chunkType\":\"operation_guide\",\"score\":0.9246347},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78007317}]', NULL, NULL, NULL, NULL, '2026-05-21 11:43:54', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (410, 179, 'user', '如何使用建模出图工具这个功能？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:43:54', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (411, 179, 'assistant', '以下是使用「建模出图工具」的操作步骤：\n\n1. **前置条件**：先**打开配置表**（含基本属性工作表），如需修改球标大小、加工说明等，须在此表中提前设置；  \n2. 填写**模具编号**（依赖配置表已打开）；  \n3. 选择要出图的零件类型：**常规出图零件** 或 **轻量化出图零件**；  \n4. 选择投影视角：**第一视角** 或 **第三视角**；  \n5. 设置视图及符号：勾选需投影的视图（默认主/右/前视图）、**球标图**、**线割涂色**、**研磨符号**；  \n6. 配置球标与注解选项：设置**球标大小**，按需勾选**加工说明**、**英文注解**、**英制牙**，选择**做深/掏留**、**槽注解**；  \n7. 填写**图纸路径**（最后一步，必须指定）；  \n8. 点击**确定**执行出图，完成后前往图纸路径查看结果。  \n\n(参考: 建模出图工具-operation_guide)', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/cae11a9be14d4c6d8093040d8705b7c1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35652167},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.31158954},{\"featureName\":\"建模出图工具\",\"chunkType\":\"operation_guide\",\"score\":0.9246347},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78701615},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.78007317}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:01', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (412, 180, 'user', '如何使用快速涂色赋注解这个功能？', '快速涂色赋注解', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:02', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (413, 180, 'assistant', '以下是使用「快速涂色赋注解」功能的完整操作指引：\n\n前置条件：**必须先设置建模档出图标准**，否则工件分析功能不可用。\n\n1. **选择设计标准**  \n　　在工具主界面点击「选择设计标准」，根据客户要求选定对应标准（如启泰标准）。\n\n2. **打开工件分析**  \n　　点击「工件分析」→ 框选需处理的多个实体 → 设置“大板是否注解槽”等参数 → 点击分析，生成孔识别结果与待处理列表。\n\n3. **上色**  \n　　在「材质颜色（体色）」中选择对应材质色 → 弹出「选择实体」对话框 → 选中目标实体完成上色；  \n　　或勾选「选择涂色」→ 在「加工颜色（面色）」中选色 → 「选择面」→ 选中目标面。\n\n4. **修改/添加注解**  \n　　在分析结果列表中检查并修改已有注解；  \n　　也可**选面后点击「注释」按钮**，在弹出文本框中编辑内容，按**回车确认**。\n\n（参考: 快速涂色赋注解-operation_guide）', '快速涂色赋注解', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/1ad500d9a8634e38a4ab0015bc0efdbd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35740045},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.33634752},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"operation_guide\",\"score\":0.93259734},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:09', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (414, 181, 'user', '如何使用快速涂色赋注解这个功能？', '快速涂色赋注解', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:10', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (415, 181, 'assistant', '以下是使用「快速涂色赋注解」功能的操作步骤：\n\n1. **前置条件：设置设计标准**  \n   进入【建模档出图标准设置】，选择适用的设计标准（如启泰标准）；未设置则分析功能不可用。\n\n2. **工件分析**  \n   点击【工件分析】→ 框选需处理的多个实体 → 设置“大板是否注解槽”等参数 → 开始分析，生成孔识别结果与待处理列表。\n\n3. **上色**  \n   在【材质颜色（体色）】中选择材质对应颜色 → 弹出“选择实体”对话框 → 选中目标实体完成上色。\n\n4. **赋注解**  \n   - 自动注解：基于分析结果，在下方列表检查并修改孔注释；  \n   - 手动添加：点击【特征注解表】→ 选面 → 在文本框输入内容，**按回车确认**。\n\n（参考: 快速涂色赋注解-operation_guide）', '快速涂色赋注解', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/1ad500d9a8634e38a4ab0015bc0efdbd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35740045},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.33634752},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"operation_guide\",\"score\":0.93259734},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:16', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (416, 182, 'user', '如何使用快速涂色赋注解这个功能？', '快速涂色赋注解', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:16', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (417, 182, 'assistant', '以下是使用「快速涂色赋注解」功能的完整操作步骤：\n\n前置条件：**必须先设置建模档出图标准**，否则分析功能不可用。\n\n1. **选择设计标准**  \n　　在功能入口处选择客户对应的设计标准（如启泰标准），未设置将弹出提示。\n\n2. **打开工件分析**  \n　　点击「工件分析」→ 框选多个实体 → 设置“大板是否注解槽”等参数 → 开始分析；分析结果生成待处理孔列表。\n\n3. **上色**  \n　　在「材质颜色（体色）」中选择材质 → 弹出「选择实体」对话框 → 选取需上色的体；  \n　　或勾选「选择涂色」→ 在「加工颜色（面色）」中选色 → 「选择面」对话框中选取面。\n\n4. **修改/添加注解**  \n　　在分析结果列表中检查孔识别情况；  \n　　选面后点击「注释」→ 在文本框中修改内容，**按回车确认保存**。\n\n（参考: 快速涂色赋注解-operation_guide）', '快速涂色赋注解', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/1ad500d9a8634e38a4ab0015bc0efdbd.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35740045},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.33634752},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"operation_guide\",\"score\":0.93259734},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924},{\"featureName\":\"快速涂色赋注解\",\"chunkType\":\"dependency\",\"score\":0.80570924}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (418, 183, 'user', '赋属性工具中编辑原点的功能如何使用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (419, 183, 'assistant', '以下是「赋属性工具」中**编辑原点**功能的使用步骤：\n\n前置条件：必须先勾选**检查原点**，否则无法显示坯料框，无法选择工件。\n\n1. 在界面中勾选 **「检查原点」**（自动显示所有坯料框）  \n2. **选择单个或多个工件**（可框选或按配置表全选）  \n3. 进入 **「编辑原点」** 功能区，调整所选工件的原点位置  \n4. 点击 **「应用更新」**（使修改临时生效）  \n5. 最后点击 **「确定」**（持久化保存修改）\n\n⚠️ 注意：跳过任一环节（如未勾选检查原点、未点“应用更新”或未点“确定”）将导致操作无效。(参考: 赋属性工具-operation_guide)', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.28229034},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.26576188},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8726206},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.76713276}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:30', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (420, 184, 'user', '赋属性工具中编辑原点的功能如何使用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:30', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (421, 184, 'assistant', '以下是「赋属性工具」中**编辑原点**功能的使用步骤：\n\n前置条件：必须先勾选**检查原点**，否则无法显示坯料框，无法选择工件。\n\n1. 在界面中勾选 **「检查原点」**（此操作将显示所有坯料框）  \n2. 选择**单个或多个工件**（可点击或框选）  \n3. 进入「编辑原点」功能，调整所选工件的原点位置  \n4. 点击 **「应用更新」**（关键步骤，不点击则修改不生效）  \n5. 最后点击 **「确定」**（使修改持久化保存）\n\n注意：跳过任一环节（如未勾选检查原点、未点“应用更新”或未点“确定”）均会导致操作无效。(参考: 赋属性工具-operation_guide)', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.28229034},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.26576188},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8726206},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.76713276}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:36', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (422, 185, 'user', '赋属性工具中编辑原点的功能如何使用？', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:36', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (423, 185, 'assistant', '(参考:赋属性工具-operation_guide)\n\n编辑原点功能用于修改单个或多个工件的原点位置，操作需严格按顺序执行：\n\n前置条件：必须先勾选「检查原点」，否则无法显示坯料框，后续操作不可进行。\n\n1. **勾选「检查原点」**  \n   → 在赋属性工具界面找到并勾选该选项，使所有坯料框可见；\n\n2. **选择工件**  \n   → 单击或框选目标工件（支持多选）；\n\n3. **修改原点位置**  \n   → 在弹出的编辑面板中调整原点坐标或拖动定位；\n\n4. **点击「应用更新」**  \n   → 使修改即时生效（跳过此步则修改不生效）；\n\n5. **点击「确定」**  \n   → 完成持久化保存，退出编辑。\n\n注意：删除属性后需重新赋属性才能再次编辑原点。(参考:赋属性工具-prerequisite)', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4fca167497654a23b788455dcfbae73a.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.28229034},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.26576188},{\"featureName\":\"赋属性工具\",\"chunkType\":\"operation_guide\",\"score\":0.8726206},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"prerequisite\",\"score\":0.8264395},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.76713276}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:42', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (424, 186, 'user', '如何使用建模档合并订料的删除实体功能？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:42', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (425, 186, 'assistant', '以下是使用「建模档合并订料」中**删除实体**功能的操作步骤：\n\n1. 在「建模档合并订料」界面，**单击“删除实体”按钮**；  \n2. 弹出“选择需要移除的实体”UI对话框；  \n3. 在对话框中**勾选要删除的目标实体**，确认后完成移除。\n\n前置条件：确保所选实体**尚未完成备料**（已备料的实体无法被选中）；若界面显示异常，可先启用「隐藏已备料」功能进行筛选，确保只操作未备料对象。(参考: 建模档合并订料-feature_detail)', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5bfd74da2d7147fc8acd601e4f1d3b1c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/db20955408c14f1088771357cb22e63c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.6429899},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35099238},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.83861476},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7376036}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:47', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (426, 187, 'user', '如何使用建模档合并订料的删除实体功能？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:47', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (427, 187, 'assistant', '1. 在「建模档合并订料」功能界面中，找到并**单击“删除实体”按钮**；  \n2. 弹出“选择需要移除的实体”UI对话框；  \n3. 在对话框中**勾选需删除的目标实体**，确认移除。  \n\n前置条件：确保所选实体尚未完成备料（已备料实体不可被选中）；建议勾选「隐藏已备料」功能以准确筛选未备料对象。(参考:建模档合并订料-feature_detail)', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5bfd74da2d7147fc8acd601e4f1d3b1c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/db20955408c14f1088771357cb22e63c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.6429899},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35099238},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.83861476},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7376036}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:51', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (428, 188, 'user', '如何使用建模档合并订料的删除实体功能？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:52', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (429, 188, 'assistant', '以下是使用「建模档合并订料」中**删除实体**功能的操作步骤：\n\n1. 在「建模档合并订料」界面，**单击“删除实体”按钮**；  \n2. 弹出“选择需要移除的实体”UI对话框；  \n3. 在对话框中**勾选需删除的目标实体**，确认移除。\n\n前置条件：确保所选实体**尚未完成备料**（已备料的实体无法被选中）；如界面显示异常，可先启用「隐藏已备料」功能进行筛选，确保仅操作未备料对象。(参考: 建模档合并订料-feature_detail)', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/6bdb75666dd942d58f7429dff68abda1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/8e9402782fa64b54be2157f25d216639.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0c71e5d2a27143a79f3eb01fd7199bd4.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/6428740afb7b44e1a157f9df5a6d4f9f.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5bfd74da2d7147fc8acd601e4f1d3b1c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/db20955408c14f1088771357cb22e63c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.6429899},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35099238},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.83861476},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"caution\",\"score\":0.7376036}]', NULL, NULL, NULL, NULL, '2026-05-21 11:44:57', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (430, 189, 'user', '快速涂色功能具体如何使用？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:44:57', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (431, 189, 'assistant', '以下是「快速涂色」功能的具体使用步骤：\n\n1. **前置条件**：先选择设计标准（如启泰品牌标准），否则会提示“找不到配置表”；  \n2. 选择需操作的配置表：  \n　　- 点击“特征注解表” → 单击**打开配置表**，配置特征等参数；  \n　　- 或点击“材质颜色表” → 单击**打开配置表**，配置材质颜色等参数；  \n3. 勾选**选择涂色**，然后：  \n　　- 勾选目标面/体所在图层；  \n　　- 在“加工颜色（面色）”中选色 → 弹出“选择面”对话框 → 手动选取面；  \n　　- 在“材质颜色（体色）”中选色 → 弹出“选择实体”对话框 → 手动选取体；  \n　　- 注意：除“任意色”外，其他颜色需通过配置表修改色号。\n\n（参考: 快速涂色-feature_detail）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7437954},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.34567127},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.80918795},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.8011743},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7945772}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:04', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (432, 190, 'user', '快速涂色功能具体如何使用？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:04', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (433, 190, 'assistant', '以下是「快速涂色」功能的完整操作指引：\n\n1. **前置条件**：先在软件中**选择设计标准**（如启泰品牌标准），未设置将无法加载配置表；  \n2. 点击「特征注解表」或「材质颜色表」→ 单击**“打开配置表”**，完成特征/颜色参数配置；  \n3. 勾选**“选择涂色”**，再勾选需上色对象所在的图层；  \n4. 在**“加工颜色（面色）”**中选色 → 弹出“选择面”对话框 → 手动选取目标面；  \n5. 在**“材质颜色（体色）”**中选色 → 弹出“选择实体”对话框 → 手动选取目标体；  \n> 注：除“任意色”外，其他颜色需通过配置表修改色号。(参考:快速涂色-feature_detail)', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7437954},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.34567127},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.80918795},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.8011743},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7945772}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (434, 191, 'user', '快速涂色功能具体如何使用？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (435, 191, 'assistant', '以下是「快速涂色」功能的具体使用步骤：\n\n1. **前置条件**：先选择设计标准（如启泰品牌标准），否则会提示“找不到配置表”；  \n2. 选择需操作的对象类型（体、孔、键槽、面）；  \n3. 进入「快速涂色」界面，勾选 **“选择涂色”**；  \n4. 勾选目标对象所在图层；  \n5. 在 **“加工颜色（面色）”** 区域选择材质颜色 → 弹出“选择面”对话框 → 手动选取需上色的面；  \n6. 在 **“材质颜色（体色）”** 区域选择材质颜色 → 弹出“选择实体”对话框 → 手动选取需上色的体；  \n7. 注意：除“任意色”外，其他颜色色号需通过配置表修改（点击“打开配置表”，选择“特征注解表”或“材质颜色表”进行配置）。\n\n(参考: 快速涂色-feature_detail)', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7437954},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.34567127},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.80918795},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.8011743},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7945772}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:17', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (436, 192, 'user', '建模出图工具是做什么用的？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:18', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (437, 192, 'assistant', '智一「建模出图工具」是用于将3D建模档自动导出为2D工程图的专用功能。\n\n典型应用场景包括：  \n1. **常规零件出图**：快速生成主视图、右视图、前视图等标准投影视图；  \n2. **轻量化出图**：针对结构简单零件，输出精简版2D图以提升效率；  \n3. **符号与注解配置**：支持线割涂色（默认红色186）、球标图、研磨符号、加工说明、英文注解等工艺标注。\n\n该工具依赖「配置表」和「基本属性表」，需按顺序完成模具编号填写、视角选择、视图设置等步骤，是建模后标准化出图流程的关键环节。（参考: 建模出图工具-feature_intro）', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.30495808},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.25624877},{\"featureName\":\"建模出图工具\",\"chunkType\":\"feature_intro\",\"score\":0.89293945},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"prerequisite\",\"score\":0.7263198}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:23', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (438, 193, 'user', '建模出图工具是做什么用的？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (439, 193, 'assistant', '智一「建模出图工具」是用于将3D建模档自动导出为2D工程图的专用功能。\n\n典型应用场景包括：  \n1. **常规制图**：选择常规出图零件，按第一或第三视角生成主视图、右视图、前视图等标准投影视图；  \n2. **轻量化出图**：针对轻量化模型快速生成简化2D图，适配快速评审与加工沟通；  \n3. **符号标注自动化**：自动添加球标图、线割涂色（默认红色186）、研磨符号等工艺标识，支持槽注解、加工说明、英制牙等配置。\n\n该工具依赖配置表（含基本属性工作表）启动，所有参数设置（如模具编号、视角、球标大小、图纸路径）需按严格顺序执行，是「建模→配置→出图」流程中的关键输出环节。(参考: 建模出图工具-feature_intro)', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.30495808},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.25624877},{\"featureName\":\"建模出图工具\",\"chunkType\":\"feature_intro\",\"score\":0.89293945},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"prerequisite\",\"score\":0.7263198}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:31', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (440, 194, 'user', '建模出图工具是做什么用的？', '建模出图工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:31', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (441, 194, 'assistant', '智一「建模出图工具」是用于将3D建模档自动导出为2D工程图的专用功能。\n\n典型应用场景包括：  \n1. **常规出图**：为标准零件快速生成主视图、右视图、前视图等标准投影视图；  \n2. **轻量化出图**：针对结构简单或需快速交付的零件，生成简化版2D图；  \n3. **符号标注**：自动添加球标图、线割涂色（默认红色186）、研磨符号等工艺标识。\n\n该工具依赖「配置表」和「基本属性表」，需按顺序完成模具编号填写、视角选择（第一/第三角）、视图配置及图纸路径设定，是建模到制造交付的关键衔接环节。(参考: 建模出图工具-feature_intro)', '建模出图工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/2a162c18599b446c95f566b92c3d7058.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.30495808},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.25624877},{\"featureName\":\"建模出图工具\",\"chunkType\":\"feature_intro\",\"score\":0.89293945},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7375484},{\"featureName\":\"建模出图工具\",\"chunkType\":\"prerequisite\",\"score\":0.7263198}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (442, 195, 'user', '零件刻字这个功能主要用户做什么？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:37', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (443, 195, 'assistant', '「零件刻字工具」是智一平台中用于在建模文件完成属性赋值后，**在指定几何面上自动生成带属性信息（如编号、材质、热处理等）的刻字特征**的功能。\n\n典型应用场景包括：  \n1. **非标件标识**：在机加工前于零件平面或圆柱面自动刻印编号、材质等关键属性；  \n2. **正/反向定位刻字**：选择平面左半边正向放置文字，右半边则反向放置，适配装配方向需求；  \n3. **多类型刻字方式**：支持分割面、凹槽、凸起等多种刻字形式，满足不同工艺要求。\n\n该功能依赖前置的“建模档排序赋属性”流程，且必须执行“更新显示”后才生成实际刻字实体，与「属性管理」「建模排序」等功能紧密协同。(参考:零件刻字-feature_intro)', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3525817},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3076044},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.8988741},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (444, 196, 'user', '零件刻字这个功能主要用户做什么？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (445, 196, 'assistant', '「零件刻字工具」是智一平台中用于在建模档完成属性赋值后，**在指定几何面上自动生成带属性信息（如编号、材质、热处理等）的刻字特征**的功能。\n\n典型应用场景包括：  \n1. **非标件标识**：在零件平面或圆柱面上刻印唯一编号、材质代号，便于生产识别；  \n2. **工艺追溯**：在分割面、凹槽或凸起区域刻写热处理状态，支持质量管控；  \n3. **正/反向适配**：根据选择平面左/右半边自动正置或反置文字，适配装配方向需求。\n\n该功能依赖于前置的“建模档排序赋属性”流程，且必须执行“更新显示”后才能生成实际刻字实体，后续尺寸与位置调整才生效。（参考:零件刻字-feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3525817},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3076044},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.8988741},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:50', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (446, 197, 'user', '零件刻字这个功能主要用户做什么？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:50', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (447, 197, 'assistant', '「零件刻字工具」是智一平台中用于在建模文件完成属性赋值后，**在指定几何面上自动生成带属性信息（如编号、材质、热处理等）的刻字特征**的功能。\n\n典型应用场景包括：  \n1. **非标件标识**：在机加工前于零件平面或圆柱面自动刻印编号、材质等关键属性；  \n2. **正/反向定位刻字**：选择平面左半边正向放置文字，右半边则反向放置，适配装配方向需求；  \n3. **多类型刻字方式**：支持分割面、凹槽、凸起等多种刻字形式，满足不同工艺要求。\n\n该功能依赖前置的“建模档排序赋属性”流程，且必须执行“更新显示”后才生成实际刻字实体，与「属性管理」「建模排序」等功能紧密协同。(参考:零件刻字-feature_intro)', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.3525817},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3076044},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.8988741},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.74477977}]', NULL, NULL, NULL, NULL, '2026-05-21 11:45:57', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (448, 198, 'user', '零刻刻字功能,有几种刻字方式？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:45:57', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (449, 198, 'assistant', '「零件刻字功能」是智一平台中用于在建模档（已完成排序与属性赋值）上生成带属性文字标识的专用工具。\n\n支持以下**3种刻字方式**：  \n1. **分割面刻字**：在模型分割面上直接刻写；  \n2. **凹槽刻字**：以凹陷形式刻入表面；  \n3. **凸起刻字**：以凸出形式呈现文字。\n\n该功能依赖前置步骤完成（如选择刻字类型、位置），且必须执行“更新显示”后，刻字实体才实际生成，后续尺寸/位置调整才生效。（参考: 零件刻字 - feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/dd104752e2144e97a3ab7607363af158.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36451617},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.36125597},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.7520205},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:02', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (450, 199, 'user', '零刻刻字功能,有几种刻字方式？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:03', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (451, 199, 'assistant', '「零件刻字功能」是智一提供的用于在建模档（已完成排序赋属性）上生成带属性文字的专用工具。\n\n支持以下**3种刻字方式**：  \n1. **分割面刻字**：在模型分割面上直接刻入文字；  \n2. **凹槽刻字**：以凹陷形式刻入文字，适用于需嵌入式标识的场景；  \n3. **凸起刻字**：以凸出形式生成文字，常用于铭牌、标牌等外露标识。\n\n该功能依赖于前置步骤（如选择刻字类型、位置），且**必须执行“更新显示”后，刻字实体才实际生成**，后续尺寸与位置调整才有作用对象。（参考: 零件刻字 - feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/dd104752e2144e97a3ab7607363af158.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36451617},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.36125597},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.7520205},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:08', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (452, 200, 'user', '零刻刻字功能,有几种刻字方式？', '零件刻字', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:09', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (453, 200, 'assistant', '「零件刻字功能」是智一提供的用于在建模档（已完成排序赋属性）上按指定属性自动刻印文字的工具。\n\n它支持以下**3种刻字方式**：  \n1. **分割面刻字**——在面分割区域上刻字；  \n2. **凹槽刻字**——在凹陷区域中刻字；  \n3. **凸起刻字**——在凸起区域中刻字。\n\n此外，刻字前需先选择**平面或圆柱面**作为载体，并可指定左/右半边以控制正/反放置方向；字高、字宽及宽高比均可自定义，方位限制为旋转面平行方向和四方移动。\n\n该功能依赖于前置的“建模档排序赋属性”流程，且必须执行“更新显示”后刻字实体才真正生成。（参考: 零件刻字 - feature_intro）', '零件刻字', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/fa8aacbb3dad40d3890daacc808862c3.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/99168bc029ca4dd2ae4be8f82f6aa8da.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/dd104752e2144e97a3ab7607363af158.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36451617},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.36125597},{\"featureName\":\"零件刻字\",\"chunkType\":\"feature_intro\",\"score\":0.7520205},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897},{\"featureName\":\"零件刻字\",\"chunkType\":\"dependency\",\"score\":0.6875897}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:15', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (454, 201, 'user', '快速涂色这个功能主要用户做什么？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:16', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (455, 201, 'assistant', '智一「快速涂色」功能主要用于**对建模档中的体、孔、键槽、面进行批量切换颜色**。\n\n典型应用场景包括：  \n1. **按设计标准统一着色**：根据品牌（如启泰）选择对应设计标准，自动匹配图层与材质颜色；  \n2. **精细化颜色配置**：通过“特征注解表”或“材质颜色表”配置参数，实现结构化上色；  \n3. **手动选择性涂色**：勾选特定图层，对选定的面或实体分别设置“加工颜色（面色）”和“材质颜色（体色）”。\n\n该功能依赖于**设计标准设置与配置表加载**，与其他颜色管理功能（如材质库调用）协同工作，是出图前可视化优化的关键环节。（参考: 快速涂色 - feature_detail）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7039099},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.32448876},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.74883443},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7387168},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7290655}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:22', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (456, 202, 'user', '快速涂色这个功能主要用户做什么？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:22', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (457, 202, 'assistant', '**快速涂色**是智一平台的「快速改色工具」，主要用于对建模档中的**体、孔、键槽、面**进行批量颜色切换。\n\n典型应用场景包括：  \n1. **按设计标准统一着色**：根据品牌（如启泰）选择对应出图标准，自动匹配图层与材质颜色；  \n2. **精细化颜色配置**：通过“特征注解表”或“材质颜色表”配置参数，实现结构化上色；  \n3. **手动选择性涂色**：勾选特定图层，对选定的面或实体分别设置面色（加工颜色）与体色（材质颜色）。\n\n该功能依赖于“设计标准”前置设置，并需配合配置表使用，与「特征识别」「材质管理」等模块协同工作。（参考: 快速涂色 - feature_detail）', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7039099},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.32448876},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.74883443},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7387168},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7290655}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:28', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (458, 203, 'user', '快速涂色这个功能主要用户做什么？', '快速涂色', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:28', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (459, 203, 'assistant', '**快速涂色**是智一平台的「快速改色工具」，用于对建模档中的**体、孔、键槽、面**进行批量颜色切换。\n\n典型应用场景包括：  \n1. **按设计标准统一着色**：根据品牌（如启泰）选择对应设计标准，批量设置图层、材质类型与颜色；  \n2. **精细化颜色配置**：通过“特征注解表”或“材质颜色表”打开配置表，调整特征参数或材质颜色参数；  \n3. **手动精准上色**：勾选“选择涂色”，在指定图层中选取特定面或实体，分别设置面色（加工颜色）与体色（材质颜色）。\n\n该功能依赖配置表与设计标准，需先完成标准选择，否则可能提示“找不到配置表”。(参考: 快速涂色-feature_detail)', '快速涂色', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/92eb0f4545af41aeaa75666a8fe0a318.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cf401ced7384db59b82917662a06e08.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7ee716b7d57a4c02a63f1f7345dce681.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/32f1a15803ce4514a523a7a05425f5a3.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"快速涂色功能报错：找不到配置表\",\"chunkType\":\"FAQ\",\"score\":0.7039099},{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.32448876},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.74883443},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7387168},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.7290655}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:34', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (460, 204, 'user', '建模档出图预设功能需要填写哪些公共信息？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:34', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (461, 204, 'assistant', '「建模档出图预设」是用于设置出图标准与公共信息（如客户、模号等）的配置功能，支持公共信息自动关联出图及导BOM。\n\n需填写的公共信息**并非固定**，而是由系统级的「基本属性配置表」动态决定，典型可填字段包括：  \n1. **客户**——用于图纸标题栏和BOM归属标识；  \n2. **模号**——关联模具项目，支撑出图命名与归档；  \n3. 其他字段（如产品名称、设计者、版本号等）依当前所选用户标准在配置表中的启用情况而定。\n\n⚠️ 注意：必须**先选择用户标准**，系统才加载对应配置表中已启用的字段；未配置的字段不会显示，也不能手动添加。（参考: 出图预设 - feature_intro）', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d185b8cecec3455997ea3739bc436f4f.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.4145788},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3500699},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.9618698},{\"featureName\":\"出图预设\",\"chunkType\":\"caution\",\"score\":0.8066035},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.803983}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:40', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (462, 205, 'user', '建模档出图预设功能需要填写哪些公共信息？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:41', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (463, 205, 'assistant', '建模档出图预设功能中，需填写的**公共信息字段不固定**，具体取决于所选「用户标准」在系统中配置的基本属性。操作步骤如下：\n\n1. **前置条件**：确保已由管理员在「基本属性配置表」中为当前用户标准启用了所需字段（如客户、模号等）；若未启用，需联系管理员配置。  \n2. 选择用户标准（步骤一）→ 系统据此加载对应的基本属性配置表。  \n3. 填写公共信息（步骤二）→ 仅显示该标准下已配置为“公共信息项”的字段，不可自由增删。\n\n错误做法：跳过第一步直接填写，或假设“客户”“模号”等字段默认存在。（参考: 出图预设-operation_guide）', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b910649ba6e147578475c7ae5468d788.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d185b8cecec3455997ea3739bc436f4f.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.4145788},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3500699},{\"featureName\":\"出图预设\",\"chunkType\":\"operation_guide\",\"score\":0.9547618},{\"featureName\":\"出图预设\",\"chunkType\":\"caution\",\"score\":0.8066035},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.803983}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:47', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (464, 206, 'user', '建模档出图预设功能需要填写哪些公共信息？', '出图预设', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:47', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (465, 206, 'assistant', '「建模档出图预设」是用于设置出图标准与公共信息（如客户、模号等）的配置功能，支持公共信息自动关联出图及导BOM。\n\n需填写的公共信息**并非固定**，而是由系统级的「基本属性配置表」动态决定，典型可填字段包括：  \n1. **客户**——用于图纸标题栏和BOM归属标识；  \n2. **模号**——关联模具项目，支撑出图命名与归档；  \n3. 其他字段（如产品名称、设计者、版本号等）依当前所选用户标准在配置表中的启用情况而定。\n\n⚠️ 注意：必须**先选择用户标准**，系统才加载对应配置表中已启用的字段；未配置的字段不会显示，也不能手动添加。（参考: 出图预设 - feature_intro）', '出图预设', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d185b8cecec3455997ea3739bc436f4f.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.4145788},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.3500699},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.9618698},{\"featureName\":\"出图预设\",\"chunkType\":\"caution\",\"score\":0.8066035},{\"featureName\":\"出图预设\",\"chunkType\":\"dependency\",\"score\":0.803983}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:53', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (466, 207, 'user', '介绍一下赋属性工具这个功能的作用。', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:53', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (467, 207, 'assistant', '**赋属性工具**是智一平台中用于为建模档实体批量生成和管理关键工程属性的功能，是出图前的必要准备步骤。\n\n典型应用场景包括：\n1. **自动生成零件编号、长宽高、材质、热处理、重量、页码等标准属性**，满足图纸输出规范；\n2. **按客户或企业标准（如上/下模俯仰视图、颜色标记原点）智能排序与赋值**；\n3. **支持删除全部属性后重新写入**，适用于模型结构调整后的属性重置需求。\n\n该工具与「出图」功能强依赖，所赋属性将直接驱动后续图纸生成；操作时需严格遵循「删除属性 → 确认生效 → 写入属性」顺序，避免新旧属性混杂。（参考: 赋属性工具-feature_intro）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6e633cc34b078c5122d0fe42b074.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32320306},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.31693467},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9166168},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105}]', NULL, NULL, NULL, NULL, '2026-05-21 11:46:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (468, 208, 'user', '介绍一下赋属性工具这个功能的作用。', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:46:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (469, 208, 'assistant', '智一「赋属性工具」是为建模档实体**批量生成并写入标准化工程属性**的功能，是出图前的关键准备步骤。\n\n典型应用场景包括：\n1. **自动标注零件编号**：按客户标准或配置表对工件进行排序编号；\n2. **批量写入物理属性**：如长宽高、材质、热处理、重量、页码等；\n3. **统一管理原点与坐标**：支持编辑原点位置、设置出图坐标、标记原点方向（如四面分中/左下角）。\n\n该工具需配合「删除属性」操作使用——**必须先确认删除生效，再执行写入**，否则会导致新旧属性混杂或覆盖失败。（参考: 赋属性工具-feature_intro）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6e633cc34b078c5122d0fe42b074.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32320306},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.31693467},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9166168},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105}]', NULL, NULL, NULL, NULL, '2026-05-21 11:47:05', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (470, 209, 'user', '介绍一下赋属性工具这个功能的作用。', '赋属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:47:05', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (471, 209, 'assistant', '**赋属性工具**是智一平台中用于为建模档实体批量生成和管理关键工程属性的功能，是出图前的必要准备步骤。\n\n典型应用场景包括：\n1. **自动生成零件编号、长宽高、材质、热处理、重量、页码等属性**，满足图纸标准化输出要求；\n2. **按客户标准或用户自定义规则（如长宽比、尺寸阈值）智能排序与定位原点**，支持上/下模俯仰视图识别；\n3. **支持属性全量删除、原点编辑、余量添加等精细化操作**，确保属性状态干净、准确、可复用。\n\n该功能与「出图」强依赖，需在出图前完成属性写入；若需重排编号，须严格遵循「删除属性 → 确认生效 → 写入属性」的操作顺序，避免新旧属性混杂。（参考: 赋属性工具-feature_intro）', '赋属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/431a6e633cc34b078c5122d0fe42b074.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.32320306},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.31693467},{\"featureName\":\"赋属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9166168},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105},{\"featureName\":\"赋属性工具\",\"chunkType\":\"dependency\",\"score\":0.77022105}]', NULL, NULL, NULL, NULL, '2026-05-21 11:47:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (472, 210, 'user', '介绍一下赋注解属性这个功能的作用。', '赋注解属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:47:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (473, 210, 'assistant', '**赋注解属性工具**是智一平台中用于UG建模档的注解分析、预览与修改的专业功能。\n\n其主要作用包括：  \n1. **分析预览零件注解**：自动识别并展示模型中已有的注解（如沉头孔、槽等），支持按面或工件层级预览；  \n2. **灵活配置注解规则**：可设置沉头孔为“做深”或“掏留”，控制大板是否注解槽，以及统一调整注解图元的字体大小与颜色；  \n3. **辅助人工标注管理**：支持手动添加注解，并与自动分析结果统一管理、展示图元/图层+编号。\n\n该功能依赖“自动分析注解”作为前置步骤，后续的展示与编号动作均基于分析结果展开。（参考: 赋注解属性工具-feature_intro）', '赋注解属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/29dd4267d56446739470d0637f77b837.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36330143},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.32296157},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9079393},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"dependency\",\"score\":0.7847868}]', NULL, NULL, NULL, NULL, '2026-05-21 11:47:17', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (474, 211, 'user', '介绍一下赋注解属性这个功能的作用。', '赋注解属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:47:17', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (475, 211, 'assistant', '**赋注解属性工具**是智一平台中用于UG建模文件分析、预览及修改零件注解的专用功能。\n\n典型应用场景包括：  \n1. **分析预览注解**：自动检查UG模型中已有的沉头孔、槽等特征的注解状态（如“做深”或“掏留”）；  \n2. **批量控制注解规则**：对大板类零件，可统一设置“不注解槽”或“注解/不注解所有槽”；  \n3. **自定义注解样式**：支持调整图元字体大小、注解颜色等显示参数，提升图纸可读性与规范性。\n\n该功能依赖「自动分析注解」作为前置步骤，后续的「手动添加注解」「图元展示」「图层+编号」等操作均基于分析结果展开。（参考: 赋注解属性工具-feature_intro）', '赋注解属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/29dd4267d56446739470d0637f77b837.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36330143},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.32296157},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9079393},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"dependency\",\"score\":0.7847868}]', NULL, NULL, NULL, NULL, '2026-05-21 11:47:23', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (476, 212, 'user', '介绍一下赋注解属性这个功能的作用。', '赋注解属性工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:47:24', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (477, 212, 'assistant', '**赋注解属性工具**是智一平台中用于UG建模档的注解分析、预览与修改的专业功能。\n\n其主要作用包括：  \n1. **分析预览零件注解**：自动识别并展示模型中已有的注解（如沉头孔、槽等），支持按面或工件层级预览；  \n2. **灵活配置注解规则**：可设置沉头孔为“做深”或“掏留”，控制大板是否注解槽，以及统一调整注解图元的字体大小与颜色；  \n3. **辅助人工标注管理**：支持手动添加注解，并与自动分析结果统一管理、展示图元/图层+编号。\n\n该功能依赖“自动分析注解”作为前置步骤，后续的展示与编号动作均基于分析结果展开。（参考: 赋注解属性工具-feature_intro）', '赋注解属性工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/29dd4267d56446739470d0637f77b837.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.36330143},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.32296157},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"feature_intro\",\"score\":0.9079393},{\"featureName\":\"赋注解属性工具\",\"chunkType\":\"dependency\",\"score\":0.7847868}]', NULL, NULL, NULL, NULL, '2026-05-21 11:47:29', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (478, 213, 'user', '建模档合并订料的旋转功能,有几种旋转方式？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:47:29', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (479, 213, 'assistant', '建模档合并订料的旋转功能提供**2种旋转方式**：  \n1. **左旋90度**：单击按钮后选择对象，整体逆时针旋转90°；  \n2. **右旋90度**：单击按钮后选择对象，整体顺时针旋转90°。  \n\n此外，该功能还支持**翻转操作**（左右翻转、上下翻转），但翻转不属于旋转范畴，而是独立的几何变换类型。  \n旋转与翻转均需先弹出“选择对象”对话框，再指定目标对象执行操作。（参考: 建模档合并订料-feature_detail）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f8b384b8517e43d1a054497b2e97374b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0e1b6864a21c4e8da8489c788155b425.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2742fffdec9543f891ff4c4f49ac7ff9.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/37585de86a804a6cb499ca2454f73c25.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/34e06e73701d42b8a9da910897df45e0.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/304f07507ebc413ea5167781955df8fb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9979225fed0646048032d0a289e01989.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.69022626},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.2777597},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.8417509},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.80098265}]', NULL, NULL, NULL, NULL, '2026-05-21 11:47:34', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (480, 214, 'user', '建模档合并订料的旋转功能,有几种旋转方式？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:47:35', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (481, 214, 'assistant', '建模档合并订料的旋转功能提供**2种旋转方式**：  \n\n1. **左旋90度**：单击对应按钮，选择对象后执行逆时针90°旋转；  \n2. **右旋90度**：单击对应按钮，选择对象后执行顺时针90°旋转。  \n\n此外，该功能还支持**翻转操作**（左右翻转、上下翻转）和**动态调整位置**（含重定位与手柄控制），但严格意义上的“旋转”仅指左旋与右旋两种。  \n该功能隶属于「建模档合并订料」整体流程，用于优化工件排布，配合备料板尺寸与加工行程要求。（参考: 建模档合并订料-feature_detail）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f8b384b8517e43d1a054497b2e97374b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0e1b6864a21c4e8da8489c788155b425.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2742fffdec9543f891ff4c4f49ac7ff9.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/37585de86a804a6cb499ca2454f73c25.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/34e06e73701d42b8a9da910897df45e0.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/304f07507ebc413ea5167781955df8fb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9979225fed0646048032d0a289e01989.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.69022626},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.2777597},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.8417509},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.80098265}]', NULL, NULL, NULL, NULL, '2026-05-21 11:47:40', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (482, 215, 'user', '建模档合并订料的旋转功能,有几种旋转方式？', '建模档合并订料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-21 11:47:40', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (483, 215, 'assistant', '建模档合并订料的旋转功能提供**2种旋转方式**：  \n1. **左旋90度**：单击按钮后选择对象，整体逆时针旋转90°；  \n2. **右旋90度**：单击按钮后选择对象，整体顺时针旋转90°。  \n\n此外，该功能还支持**翻转操作**（左右翻转、上下翻转），但翻转不属于旋转范畴，而是独立的几何变换类型。  \n旋转与翻转均需先弹出“选择对象”对话框，再指定目标对象执行操作。（参考: 建模档合并订料-feature_detail）', '建模档合并订料', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/f8b384b8517e43d1a054497b2e97374b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9d7e2df44ad1445ca1b071d921cf66ae.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/0e1b6864a21c4e8da8489c788155b425.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/2742fffdec9543f891ff4c4f49ac7ff9.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/37585de86a804a6cb499ca2454f73c25.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/34e06e73701d42b8a9da910897df45e0.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/304f07507ebc413ea5167781955df8fb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/9979225fed0646048032d0a289e01989.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用建模档合并订料功能,弹出备料板重量超出限定值的的提示。要...\",\"chunkType\":\"FAQ\",\"score\":0.69022626},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.2777597},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.8417509},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"feature_detail\",\"score\":0.80098265}]', NULL, NULL, NULL, NULL, '2026-05-21 11:47:45', 0, NULL, NULL);
