INSERT INTO `chat_message` VALUES (486, 217, 'user', '怎么使用 BOM 工具？', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-22 10:04:33', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (487, 217, 'assistant', '以下是使用 BOM 工具的完整操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**（前置条件：必须准确填写真实有效的信息，将写入EXCEL表头及TXT元数据，是法定追溯依据）  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：  \n　　- 勾选「已备料不出料单」  \n　　- 设置「是否分页」及「分页类型和行数」（注意：分页行数不能超过原表格最大行数，如20，否则导致乱码）  \n4. **生成BOM表**：点击「扫描所有实体出BOM表」或「选择实体生成」  \n5. **导出与转换**：点击「导出EXCEL」；如需进一步处理，再点击「EXCEL转TXT文本」（该功能仅在导出EXCEL后可用）  \n\n(参考:BOM工具-operation_guide)', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.53555596},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.33247927},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8116272},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6997263},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.69462806}]', NULL, NULL, NULL, NULL, '2026-05-22 10:04:40', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (488, 217, 'user', '转人工', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-22 10:06:33', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (489, 217, 'assistant', '好的,我来帮您提交工单,请稍候。  \n好的,我来帮您提交工单,请稍候。  \n工单已成功提交，编号为：**TK-20260522-0001**。  \n您可随时凭此编号查询处理进度。', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/7179f4f725e947338d00ba51aa0f5e6d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7de3c5c09a78469d93172798c6708062.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.45104396},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43891764}]', NULL, NULL, NULL, NULL, '2026-05-22 10:06:40', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (490, 218, 'user', '本周用户问得最多的问题是什么？', 'admin_command', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-22 10:07:59', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (491, 218, 'assistant', '我需要查询本周的使用情况统计，特别是高频关键词，来了解用户问得最多的问题。\n\n根据本周（2026-05-18 至 2026-05-22）的使用统计分析，用户提问最集中的问题聚焦在**快速涂色/上色功能异常**及相关交互反馈上，具体表现为：\n\n✅ **高频共性关键词（Top 5）**：  \n- “为什么上色功能失败”（7 次）  \n- “我在使用快速涂色功能的时候”（7 次）  \n- “该操作可删除”（9 次）  \n- “已执行某项操作”（9 次）  \n- “弹出提示框” / “弹出个提示框”（共 16 次）  \n\n⚠️ **值得关注的问题**：  \n- 用户频繁遭遇上色失败，并关联到“找不到配置表”（7 次），表明该功能依赖的配置可能缺失、路径错误或未完成知识学习；  \n- 多次提及“此对话框即将关闭”“弹出提示框”，暗示当前 UI 提示逻辑存在冗余、不明确或未妥善处理异常流程；  \n- 满意度率仅为 0.0%（仅 1 条踩，无点赞），且反馈极低（仅 1 条反馈），说明用户遇到问题后未获得有效解答，可能已产生挫败感。\n\n📌 建议下一步：  \n1. 检查「快速涂色」「零刻刻字」相关文档/视频是否已学习（可调用 `listDocumentStatus` 确认）；  \n2. 重点排查“配置表”类知识是否入库并生效；  \n3. 审视对应功能的提示文案与错误兜底逻辑。\n\n需要我帮您查询这些功能对应的知识学习状态吗？', 'admin_command', '[]', '[]', NULL, NULL, NULL, NULL, '2026-05-22 10:08:11', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (492, 219, 'user', '你好', 'chitchat', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-22 10:30:01', 0, NULL, NULL);
