INSERT INTO `chat_message` VALUES (494, 220, 'user', '怎么使用 BOM 工具', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-22 10:30:28', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (495, 220, 'assistant', '以下是使用 BOM 工具的完整操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**（前置条件：必须准确填写真实有效的图层编码、模号、产品编号，不可留空或用占位符）  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：如“已备料不出料单”、是否分页，并设置**分页类型和行数**（注意：分页行数不能超过原表格最大行数，如20，否则会导致乱码）  \n4. **生成BOM表**：点击“扫描所有实体”或手动“选择实体”生成  \n5. **导出EXCEL**：点击“导出EXCEL”按钮；导出后如需，可再点击“EXCEL转TXT文本”  \n\n（参考:BOM工具-operation_guide）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.5266784},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.31991017},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8076673},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6950949},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.68824047}]', NULL, NULL, NULL, NULL, '2026-05-22 10:30:34', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (496, 220, 'user', '转人工', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-22 10:31:23', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (497, 220, 'assistant', '好的,我来帮您提交工单,请稍候。  \n好的,我来帮您提交工单,请稍候。  \n已为您成功提交工单，编号为：**TK-20260522-0002**。  \n您可随时凭此编号查询处理进度。', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/49ac0e17be344dadb5525773e2ebaa90.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7179f4f725e947338d00ba51aa0f5e6d.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/591de5feab4740e0aa379eade7d0f573.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/358e1e928297457ea9530ed9d464176e.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.45104396},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.43891764}]', NULL, NULL, NULL, NULL, '2026-05-22 10:31:29', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (498, 221, 'user', '本周用户问得最多的问题是什么', 'admin_command', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-22 10:32:32', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (499, 221, 'assistant', '根据本周（2026-05-18 至 2026-05-22）的使用统计分析：\n\n✅ **亮点**：  \n- 总对话数达 166 次，活跃用户 2 人（管理员和普通用户），其中普通用户贡献了 152 次会话，使用非常频繁；  \n- 高频关键词高度集中于**UI交互与功能异常反馈**，说明用户正在深度使用系统，并积极报告问题，具备良好的反馈意识。\n\n⚠️ **需重点关注的问题**：  \n- 前4个高频关键词完全一致（各出现9次）：“该操作可删除”“已执行某项操作”“弹出提示框”“此对话框即将关闭”——这极可能指向**同一类自动化提示文案被反复提问**，疑似用户对系统弹窗逻辑/意图不理解，或存在误导性文案，建议产品团队核查相关交互流程与提示语设计；  \n- “为什么上色功能失败”“说是找不到配置表”“我在使用快速涂色功能的时候”等关键词密集出现（7次及以上），表明**快速涂色/零刻刻字功能存在稳定性或配置问题**，已成为当前用户痛点，亟需技术侧排查配置加载、权限或依赖表缺失等问题。\n\n📌 补充说明：  \n- 用户满意度为 0.0%（仅1次踩，无点赞），与上述功能问题强相关；  \n- 当前暂无正向体验关键词上榜，后续可结合用户反馈优化引导文案与功能健壮性，提升获得感。\n\n如需进一步定位具体会话或查看某关键词的原始提问上下文，我可协助查询。', 'admin_command', '[]', '[]', NULL, NULL, NULL, NULL, '2026-05-22 10:32:44', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (500, 222, 'user', '怎么使用 BOM 工具?', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-23 08:52:21', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (501, 222, 'assistant', '以下是使用 BOM 工具的完整操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**（前置条件：必须准确填写真实有效的信息，将写入EXCEL表头及TXT元数据，不可留空或用占位符）  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：  \n　- 勾选「已备料不出料单」  \n　- 设置「是否分页」及「分页类型和行数」（注意：分页行数不能超过原表格最大行数，如20，否则导致乱码）  \n4. **生成BOM表**：点击「扫描所有实体」或「选择实体生成」  \n5. **导出与转换**：点击「导出EXCEL」；如需，再点击「EXCEL转TXT文本」（该功能仅在导出EXCEL后可用）  \n\n(参考: BOM工具-operation_guide)', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.53555596},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.33247927},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8116272},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6997263},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.69462806}]', NULL, NULL, NULL, NULL, '2026-05-23 08:52:33', 1, NULL, NULL);
