INSERT INTO `chat_message` VALUES (505, 224, 'assistant', '以下是使用BOM工具的完整操作步骤：\n\n1. **填写并检查客户信息、模号、产品编号**（前置条件：必须准确填写真实有效的信息，将写入EXCEL表头及TXT元数据，是法定追溯依据）  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单）  \n3. **按需勾选选项**：如“已备料不出料单”，设置“是否分页”及**分页行数（不可超过原表格最大行数，如20，否则导致乱码）**  \n4. **扫描所有实体出BOM表**，或**手动选择实体生成**（依赖前两步信息填充表头与字段范围）  \n5. **点击“导出EXCEL”**；导出后如需，可再点击“EXCEL转TXT文本”\n\n（参考:BOM工具-operation_guide）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.4961486},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.32985392},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.78363514},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6750278},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.6643913}]', NULL, NULL, NULL, NULL, '2026-05-23 11:21:49', 1, NULL, NULL);
