INSERT INTO `chat_message` VALUES (510, 226, 'user', 'BOM工具的具体操作步骤给我说一下。', 'BOM工具', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-23 14:09:32', 0, NULL, NULL);
INSERT INTO `chat_message` VALUES (511, 226, 'assistant', '以下是 BOM 工具的具体操作步骤（按标准流程执行）：\n\n1. **填写并检查客户信息、模号、产品编号**（确保表头信息准确，为后续扫描提供依据）  \n2. **选择BOM表类型**（如材料清单、标准件清单、成本预算单等）  \n3. **按需勾选选项并设置分页**：  \n　　- 勾选「已备料不出料单」  \n　　- 设置「是否分页」及「分页类型和行数」（注意：分页行数**不能超过原表格最大行数（如20）**，否则导出EXCEL会乱码）  \n4. **扫描或选择实体生成BOM数据**：  \n　　- 可点击「扫描所有实体」，或手动「选择实体」生成  \n5. **点击「导出EXCEL」**（此为必要前置动作）  \n　　- 导出后，如需进一步处理，可点击「EXCEL转TXT文本」  \n\n（参考:BOM工具-operation_guide）', 'BOM工具', '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/39639fc7e9a44ae291bd620270dd0dee.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/01489e8042b6431e88e7f16506fa9720.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/74da6fb136c2470dbe0d28035a612ec1.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.5238925},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.35463676},{\"featureName\":\"BOM工具\",\"chunkType\":\"operation_guide\",\"score\":0.8183135},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.7126066},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.7027798}]', NULL, NULL, NULL, NULL, '2026-05-23 14:09:45', 1, NULL, NULL);
